fn merge_settings_defaults(defaults: &Value, current: &Value) -> Value {
    match (defaults, current) {
        (Value::Object(default_map), Value::Object(current_map)) => {
            let mut merged = serde_json::Map::new();
            for (key, default_value) in default_map {
                if let Some(current_value) = current_map.get(key) {
                    merged.insert(
                        key.clone(),
                        merge_settings_defaults(default_value, current_value),
                    );
                } else {
                    merged.insert(key.clone(), default_value.clone());
                }
            }
            for (key, current_value) in current_map {
                if !merged.contains_key(key) {
                    merged.insert(key.clone(), current_value.clone());
                }
            }
            Value::Object(merged)
        }
        _ => current.clone(),
    }
}

/// (settings.json field, credential-store account) pairs for every secret
/// that must never be persisted in the plaintext settings file.
const SECRET_SETTINGS_FIELDS: [(&str, &str); 3] = [
    ("openaiApiKey", "openai_api_key"),
    ("anthropicApiKey", "anthropic_api_key"),
    ("aiApiKey", "legacy_ai_api_key"),
];

#[tauri::command]
fn load_settings(app: tauri::AppHandle) -> Result<Value, String> {
    let path = app_data_dir(&app)?.join("settings.json");
    let value = read_json(&path)?;
    let defaults = default_settings();
    let mut merged = if value.is_null() {
        write_json(&path, &defaults)?;
        defaults
    } else {
        let merged = merge_settings_defaults(&defaults, &value);
        if merged != value {
            write_json(&path, &merged)?;
        }
        merged
    };

    // One-time migration: a secret field still holding a plaintext value on
    // disk (from before the credential store was wired in) is moved into the
    // OS credential store and blanked on disk here, mirroring this app's
    // existing idempotent-migration convention for the legacy tasks.json.
    let mut migrated = false;
    for (field, account) in SECRET_SETTINGS_FIELDS {
        if let Some(plaintext) = merged
            .get(field)
            .and_then(Value::as_str)
            .filter(|v| !v.is_empty())
        {
            secrets::store(account, plaintext)?;
            migrated = true;
        }
    }
    if migrated {
        let mut cleared = merged.clone();
        for (field, _) in SECRET_SETTINGS_FIELDS {
            cleared[field] = Value::String(String::new());
        }
        write_json(&path, &cleared)?;
    }

    // Overlay the real secret values from the credential store so callers
    // still see them — only the on-disk file omits them, never the response.
    for (field, account) in SECRET_SETTINGS_FIELDS {
        if let Some(secret) = secrets::load(account) {
            merged[field] = Value::String(secret);
        }
    }
    Ok(merged)
}

#[tauri::command]
fn save_settings(app: tauri::AppHandle, settings: Value) -> Result<(), String> {
    let path = app_data_dir(&app)?.join("settings.json");
    let mut on_disk = settings.clone();
    for (field, account) in SECRET_SETTINGS_FIELDS {
        let value = settings.get(field).and_then(Value::as_str).unwrap_or("");
        secrets::store(account, value)?;
        on_disk[field] = Value::String(String::new());
    }
    write_json(&path, &on_disk)
}

// --- Filesystem actions ----------------------------------------------------

/// Opens a folder path in the operating-system file explorer.
/// Returns an error if the path does not exist.
#[tauri::command]
fn open_path(path: String) -> Result<(), String> {
    let p = std::path::Path::new(&path);
    if !p.exists() {
        return Err(format!("Path not found: {}", path));
    }

    #[cfg(target_os = "windows")]
    {
        std::process::Command::new("explorer")
            .arg(&path)
            .spawn()
            .map(|_| ())
            .map_err(|e| e.to_string())
    }
    #[cfg(target_os = "macos")]
    {
        std::process::Command::new("open")
            .arg(&path)
            .spawn()
            .map(|_| ())
            .map_err(|e| e.to_string())
    }
    #[cfg(not(any(target_os = "windows", target_os = "macos")))]
    {
        std::process::Command::new("xdg-open")
            .arg(&path)
            .spawn()
            .map(|_| ())
            .map_err(|e| e.to_string())
    }
}


/// Opens an external web URL in Microsoft Edge.
/// Only http/https URLs are accepted, and the URL is passed as a single process
/// argument so no shell command can be injected through it.
#[tauri::command]
fn open_url_in_edge(url: String) -> Result<(), String> {
    let trimmed = url.trim().to_string();
    let lower = trimmed.to_ascii_lowercase();
    if !(lower.starts_with("http://") || lower.starts_with("https://")) {
        return Err("Only http:// and https:// URLs can be opened.".to_string());
    }

    #[cfg(target_os = "windows")]
    {
        let edge_paths = [
            "msedge",
            r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
            r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
        ];

        for edge_path in edge_paths {
            match std::process::Command::new(edge_path).arg(&trimmed).spawn() {
                Ok(_) => return Ok(()),
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => continue,
                Err(_) => continue,
            }
        }

        Err("Microsoft Edge could not be started.".to_string())
    }

    #[cfg(not(target_os = "windows"))]
    {
        Err("Microsoft Edge could not be started.".to_string())
    }
}

// --- Git helpers -----------------------------------------------------------

/// Helper: run a git command in repo_path; return trimmed stdout or an error string.
fn git_run(repo_path: &str, args: &[&str]) -> Result<String, String> {
    let p = std::path::Path::new(repo_path);
    if !p.exists() {
        return Err(format!("Repository path not found: {repo_path}"));
    }
    let mut cmd = std::process::Command::new("git");
    cmd.arg("-C").arg(repo_path).args(args);
    hide_console_window(&mut cmd);
    let output = cmd.output().map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            "git is not installed or not on PATH.".to_string()
        } else {
            format!("Failed to run git: {e}")
        }
    })?;
    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        Err(String::from_utf8_lossy(&output.stderr).trim().to_string())
    }
}


// --- Read-only Git review context collection --------------------------------

/// Runs a read-only git command in `working_dir`.  Returns trimmed stdout or `None` on failure.
fn run_git_ro(working_dir: &str, args: &[&str]) -> Option<String> {
    let mut cmd = std::process::Command::new("git");
    #[cfg(target_os = "windows")]
    hide_console_window(&mut cmd);
    cmd.arg("-C").arg(working_dir);
    for a in args {
        cmd.arg(a);
    }
    let out = cmd
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .stdin(Stdio::null())
        .output()
        .ok()?;
    if out.status.success() {
        Some(String::from_utf8_lossy(&out.stdout).trim_end().to_string())
    } else {
        None
    }
}


/// Returns `true` for paths that are typically generated/cache noise in .NET repositories.
fn is_repo_noise(path: &str) -> bool {
    let p = path.to_lowercase().replace('\\', "/");
    p.starts_with("bin/")
        || p.contains("/bin/")
        || p.starts_with("obj/")
        || p.contains("/obj/")
        || p.starts_with("packages/")
        || p.contains("/packages/")
        || p.starts_with(".vs/")
        || p.contains("/.vs/")
        || p.ends_with(".user")
        || p.ends_with(".suo")
}

/// Returns `true` for paths that should be flagged as suspicious additions.
fn is_flagged_repo_path(path: &str) -> bool {
    let p = path.to_lowercase().replace('\\', "/");
    p.contains("copilot-instructions") || (p.contains(".github/") && p.contains("instructions"))
}


