fn task_mcp_tool_definitions() -> Vec<Value> {
    let mut tools = task_mcp_read_only_tool_definitions();
    tools.extend(task_mcp_local_write_tool_definitions());
    tools
}

/// The list-item projection shared by list_work_items and get_planning_today
/// (canonical_summary above). Kept in one place so both tools' outputSchema
/// stays identical to the other and to docs/openapi.yaml's WorkItemSummary /
/// mcp/task-workbench-mcp.mjs's WORK_ITEM_SUMMARY_SCHEMA.
fn mcp_work_item_summary_schema() -> Value {
    serde_json::json!({
        "type": "object",
        "required": ["id","kind","title","status","priority","source","updatedAt","revision","archived"],
        "properties": {
            "id": {"type": "string"},
            "kind": {"enum": ["task", "obligation"]},
            "title": {"type": "string"},
            "status": {"enum": ["planned","ready","in_progress","waiting","blocked","review","completed","cancelled"]},
            "priority": {"enum": ["low","normal","high","critical"]},
            "planningBucket": {"type": ["string","null"], "description": "Explicitly stored bucket; null when unset. Never inferred."},
            "owner": {"type": ["object","null"], "properties": {"id": {"type": ["string","null"]}, "displayName": {"type": "string"}}},
            "area": {"type": ["object","null"], "properties": {"id": {"type": "string"}, "name": {"type": "string"}}},
            "dueAt": {"type": ["string","null"]},
            "estimateMinutes": {"type": ["integer","null"]},
            "source": {"type": "string"},
            "updatedAt": {"type": "string"},
            "revision": {"type": "integer", "minimum": 1},
            "archived": {"type": "boolean"}
        }
    })
}

fn canonical_mcp_tool_definitions() -> Vec<Value> {
    vec![
        serde_json::json!({"name":"list_work_items","description":"List canonical task and obligation summaries. Read-only; never executes work.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"includeArchived":{"type":"boolean"},"limit":{"type":"integer","minimum":1,"maximum":500},"cursor":{"type":"string"},"status":{"type":"string"},"kind":{"type":"string"},"owner":{"type":"string"},"area":{"type":"string"},"source":{"type":"string"},"planningBucket":{"type":"string"},"dueBefore":{"type":"string"},"dueAfter":{"type":"string"},"updatedAfter":{"type":"string"}}},"outputSchema":{"type":"object","required":["apiVersion","generatedAt","snapshotRevision","items","nextCursor"],"properties":{"apiVersion":{"const":"1"},"generatedAt":{"type":"string"},"snapshotRevision":{"type":"integer"},"items":{"type":"array","items":mcp_work_item_summary_schema()},"nextCursor":{"type":["string","null"]}}}}),
        serde_json::json!({"name":"get_work_item","description":"Get one canonical work-item detail by stable id.","inputSchema":{"type":"object","required":["id"],"additionalProperties":false,"properties":{"id":{"type":"string","minLength":1}}}}),
        serde_json::json!({"name":"get_task_record","description":"Get one full Task Workbench task record for trusted local integrations. Includes canonical work item, UI-compatible legacy task JSON, and derived workflow/status/link fields.","inputSchema":{"type":"object","required":["id"],"additionalProperties":false,"properties":{"id":{"type":"string","minLength":1}}}}),
        serde_json::json!({"name":"list_work_item_changes","description":"Read ordered changes after a revision cursor.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"after":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":1,"maximum":500}}}}),
        serde_json::json!({"name":"create_work_item","description":"Create a canonical task or obligation record only.","inputSchema":{"type":"object","required":["item"],"additionalProperties":false,"properties":{"item":{"type":"object"},"idempotencyKey":{"type":"string"}}}}),
        serde_json::json!({"name":"update_work_item","description":"Update canonical work-item data with expected revision.","inputSchema":{"type":"object","required":["id","item","expectedRevision"],"additionalProperties":false,"properties":{"id":{"type":"string"},"item":{"type":"object"},"expectedRevision":{"type":"integer","minimum":1},"actorName":{"type":"string"}}}}),
        serde_json::json!({"name":"patch_work_item","description":"Patch whitelisted canonical work-item fields with expected revision. Use for small trusted-local edits without sending the whole record.","inputSchema":{"type":"object","required":["id","patch","expectedRevision"],"additionalProperties":false,"properties":{"id":{"type":"string"},"patch":{"type":"object"},"expectedRevision":{"type":"integer","minimum":1},"actorName":{"type":"string"}}}}),
        serde_json::json!({"name":"transition_work_item","description":"Apply a validated lifecycle transition.","inputSchema":{"type":"object","required":["id","status","expectedRevision"],"additionalProperties":false,"properties":{"id":{"type":"string"},"status":{"type":"string"},"reason":{"type":"string"},"expectedRevision":{"type":"integer","minimum":1},"actorName":{"type":"string"}}}}),
        serde_json::json!({"name":"append_work_item_note","description":"Append contextual information to a work item.","inputSchema":{"type":"object","required":["id","text","expectedRevision"],"additionalProperties":false,"properties":{"id":{"type":"string"},"text":{"type":"string","minLength":1},"expectedRevision":{"type":"integer","minimum":1},"actorName":{"type":"string"}}}}),
        serde_json::json!({"name":"get_planning_today","description":"Return the live deterministic Now and Today planning sections. Membership is an exact match against each item's stored planningBucket — never inferred from dueAt/status/date. timezone is echoed back only.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"timezone":{"type":"string"}}},"outputSchema":{"type":"object","required":["apiVersion","generatedAt","sourceRevision","timezone","sections"],"properties":{"apiVersion":{"const":"1"},"generatedAt":{"type":"string"},"sourceRevision":{"type":"integer"},"timezone":{"type":"string"},"sections":{"type":"object","required":["now","today"],"properties":{"now":{"type":"array","items":mcp_work_item_summary_schema()},"today":{"type":"array","items":mcp_work_item_summary_schema()}}}}}}),
    ]
}

fn task_mcp_execute_canonical_tool(app: &tauri::AppHandle, name: &str, args: &Value) -> Result<Value, String> {
    match name {
        "list_work_items" => list_work_items(app.clone(), args["includeArchived"].as_bool(), args["limit"].as_u64().map(|v| v as usize), args["status"].as_str().map(str::to_string), args["kind"].as_str().map(str::to_string), args["owner"].as_str().map(str::to_string), args["area"].as_str().map(str::to_string), args["source"].as_str().map(str::to_string), args["planningBucket"].as_str().map(str::to_string), args["dueBefore"].as_str().map(str::to_string), args["dueAfter"].as_str().map(str::to_string), args["updatedAfter"].as_str().map(str::to_string), args["cursor"].as_str().map(str::to_string)),
        "get_work_item" => get_work_item(app.clone(), args["id"].as_str().unwrap_or_default().to_string()),
        "get_task_record" => get_task_record(app.clone(), args["id"].as_str().unwrap_or_default().to_string()),
        "list_work_item_changes" => list_work_item_changes(app.clone(), args["after"].as_i64(), args["limit"].as_u64().map(|v| v as usize)),
        "create_work_item" => { let item: WorkItem = serde_json::from_value(args["item"].clone()).map_err(|e| e.to_string())?; create_work_item(app.clone(), item, args["idempotencyKey"].as_str().map(str::to_string)) },
        "update_work_item" => { let item: WorkItem = serde_json::from_value(args["item"].clone()).map_err(|e| e.to_string())?; update_work_item(app.clone(), args["id"].as_str().unwrap_or_default().to_string(), item, args["expectedRevision"].as_i64().unwrap_or(0), args["actorName"].as_str().map(str::to_string)) },
        "patch_work_item" => patch_work_item(app.clone(), args["id"].as_str().unwrap_or_default().to_string(), args["patch"].clone(), args["expectedRevision"].as_i64().unwrap_or(0), args["actorName"].as_str().map(str::to_string)),
        "transition_work_item" => transition_work_item(app.clone(), args["id"].as_str().unwrap_or_default().to_string(), args["status"].as_str().unwrap_or_default().to_string(), args["reason"].as_str().map(str::to_string), args["expectedRevision"].as_i64().unwrap_or(0), args["actorName"].as_str().map(str::to_string)),
        "append_work_item_note" => append_work_item_note(app.clone(), args["id"].as_str().unwrap_or_default().to_string(), args["text"].as_str().unwrap_or_default().to_string(), args["expectedRevision"].as_i64().unwrap_or(0), args["actorName"].as_str().map(str::to_string)),
        "get_planning_today" => get_planning_today(app.clone(), args["timezone"].as_str().map(str::to_string)),
        _ => Err(format!("Unknown canonical tool: {name}")),
    }
}

fn task_mcp_strip_html(value: &str) -> String {
    let mut text = value
        .replace("<br>", "\n")
        .replace("<br/>", "\n")
        .replace("<br />", "\n")
        .replace("\r\n", "\n");

    while let Some(start) = text.find('<') {
        if let Some(end_rel) = text[start..].find('>') {
            let end = start + end_rel;
            text.replace_range(start..=end, " ");
        } else {
            break;
        }
    }

    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .trim()
        .to_string()
}

fn task_mcp_summarize(value: Option<&str>, max_len: usize) -> String {
    let clean = task_mcp_strip_html(value.unwrap_or(""));
    if clean.len() <= max_len {
        return clean;
    }
    format!(
        "{}...",
        clean
            .chars()
            .take(max_len.saturating_sub(3))
            .collect::<String>()
    )
}

fn task_mcp_is_developer_task(task: &Value) -> bool {
    task["taskMode"].as_str() == Some("developer")
        || task.get("crmDeveloperWorkflow").is_some()
        || task.get("workflowSetup").is_some()
        || task
            .get("crmVerificationReports")
            .and_then(|v| v.as_array())
            .is_some_and(|arr| !arr.is_empty())
}

fn task_mcp_latest_verification(task: &Value) -> Value {
    let reports = task["crmVerificationReports"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    if reports.is_empty() {
        return serde_json::json!({
            "exists": false,
            "verdict": "missing",
            "summary": "No CRM metadata verification report is stored for this task.",
        });
    }

    let report = &reports[0];
    serde_json::json!({
        "exists": true,
        "verdict": report["verdict"].as_str().or(report["status"].as_str()).unwrap_or("unknown"),
        "createdAt": report["createdAt"].as_str().or(report["generatedAt"].as_str()),
        "summary": task_mcp_summarize(report["summary"].as_str().or(report["message"].as_str()), TASK_MCP_MAX_SUMMARY_LENGTH),
        "issueCount": report["issues"].as_array().map(|a| a.len()).or(report["issueCount"].as_u64().map(|n| n as usize)),
        "inspectedEntityCount": report["inspectedEntities"].as_array().map(|a| a.len()).or(report["inspectedEntityCount"].as_u64().map(|n| n as usize)),
    })
}

fn task_mcp_approval_summary(gate: Option<&Value>) -> Value {
    let gate = gate.unwrap_or(&Value::Null);
    serde_json::json!({
        "approved": gate["approved"].as_bool().unwrap_or(false) && gate["invalidatedAt"].is_null(),
        "approvedAt": gate["approvedAt"].as_str(),
        "invalidatedAt": gate["invalidatedAt"].as_str(),
        "invalidationReason": gate["invalidationReason"].as_str(),
    })
}

fn task_mcp_plan_approval_safety_check(task: &Value, packet: &Value) -> Vec<String> {
    let mut reasons: Vec<String> = Vec::new();
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let impl_obj = &packet["implementation"];
    let plan = &workflow["technicalPlan"];

    if task["taskMode"].as_str() != Some("developer") {
        reasons.push("Task mode is not 'developer'.".to_string());
    }

    let work_kind = workflow["detectedWorkKind"]
        .as_str()
        .or_else(|| task["workflowSetup"]["devTargetKind"].as_str())
        .unwrap_or("unknown");
    if matches!(work_kind, "unknown" | "") {
        reasons.push(
            "Work kind is not yet classified. Set work kind to plugin or script.".to_string(),
        );
    }

    if plan.is_null() {
        reasons
            .push("No technical plan has been saved. Call save_technical_plan first.".to_string());
    } else {
        if !plan["invalidatedAt"].is_null() {
            reasons
                .push("Technical plan has been invalidated and must be regenerated.".to_string());
        }
        if plan["externalActionPreview"]
            .as_array()
            .map(|a| !a.is_empty())
            .unwrap_or(false)
        {
            reasons.push("Technical plan includes external actions (deploy/upload/Dataverse write). These require manual user approval and cannot be auto-approved.".to_string());
        }
        let has_todo = plan["implementationSteps"]
            .as_array()
            .map(|a| {
                a.iter().any(|v| {
                    let s = v.as_str().unwrap_or("").to_lowercase();
                    s.contains("todo") || s.contains("scaffold") || s.contains("placeholder")
                })
            })
            .unwrap_or(false)
            || plan["risks"]
                .as_array()
                .map(|a| {
                    a.iter().any(|v| {
                        let s = v.as_str().unwrap_or("").to_lowercase();
                        s.contains("todo") || s.contains("scaffold") || s.contains("placeholder")
                    })
                })
                .unwrap_or(false);
        if has_todo {
            reasons.push("Technical plan steps or risks contain TODO/scaffold/placeholder text. Regenerate the plan with concrete implementation steps.".to_string());
        }
    }

    if impl_obj["scaffoldOnly"].as_bool().unwrap_or(false) {
        reasons.push(
            "scaffoldOnly=true: required write targets or field mappings are not fully defined."
                .to_string(),
        );
    }

    if impl_obj["finalConsistencyGuardApplied"]
        .as_bool()
        .unwrap_or(false)
    {
        reasons.push("finalConsistencyGuardApplied=true: plan still contains scaffold/TODO text alongside empty field mappings.".to_string());
    }

    let requires_fm = impl_obj["requiresFieldMappings"].as_bool().unwrap_or(false);
    let fm_count = impl_obj["fieldMappings"]
        .as_array()
        .map(|a| a.len())
        .unwrap_or(0);
    let fm_source = impl_obj["fieldMappingsSource"].as_str().unwrap_or("none");
    let implementation_pattern = impl_obj["implementationPattern"].as_str();
    let is_non_mapping_pattern = matches!(
        implementation_pattern,
        Some("ui-business-rule") | Some("ribbon-action")
    );

    if requires_fm {
        if fm_count == 0 {
            reasons.push("Field mappings are required but not defined. Define source\u{2192}target field mappings in the technical plan before approving.".to_string());
        }
        if !matches!(fm_source, "template" | "plan") {
            reasons.push(format!("fieldMappingsSource='{fm_source}' is not a trusted source. Only 'template' or 'plan' field mapping sources can be auto-approved."));
        }
    } else if is_non_mapping_pattern {
        // UI/business-rule and ribbon-action scripts legitimately have no fieldMappings by design
        // (impl.requiresFieldMappings is already false for this pattern — see
        // task_mcp_developer_work_packet). Waiving the field-mapping checks above must not waive
        // scrutiny outright: the rest of the write target and business context still has to be
        // concrete before auto-approval.
        let wt = &packet["writeTarget"];
        if wt["targetEntity"].as_str().unwrap_or("").is_empty() {
            reasons.push("Target entity is not set.".to_string());
        }
        if wt["artifactPath"].as_str().unwrap_or("").is_empty() {
            reasons.push("Target file/artifact path is not set.".to_string());
        }
        if wt["eventName"].as_str().unwrap_or("").is_empty()
            && wt["eventFieldName"].as_str().unwrap_or("").is_empty()
        {
            reasons.push("Event/eventField is not set.".to_string());
        }
        let referenced_len = impl_obj["referencedFields"]
            .as_array()
            .map(|a| a.len())
            .unwrap_or(0);
        let affected_len = impl_obj["affectedFields"]
            .as_array()
            .map(|a| a.len())
            .unwrap_or(0);
        if referenced_len == 0 && affected_len == 0 {
            reasons.push(
                "No referenced/affected fields are defined for this UI/business-rule script."
                    .to_string(),
            );
        }
        if impl_obj["businessRules"]
            .as_array()
            .map(|a| a.is_empty())
            .unwrap_or(true)
        {
            reasons.push(
                "No business rules are defined for this UI/business-rule script.".to_string(),
            );
        }
        if impl_obj["acceptanceCriteria"]
            .as_array()
            .map(|a| a.is_empty())
            .unwrap_or(true)
        {
            reasons.push(
                "No acceptance criteria are defined for this UI/business-rule script.".to_string(),
            );
        }
    }

    reasons
}

fn task_mcp_safe_task_summary(task: &Value) -> Value {
    let analysis = task.get("analysisResult").unwrap_or(&Value::Null);
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let summary_source = analysis["summaryEn"]
        .as_str()
        .or(analysis["summary"].as_str())
        .or(task["title"].as_str());

    let mut result = serde_json::json!({
        "id": task["id"].as_str().unwrap_or(""),
        "title": task["title"].as_str().unwrap_or(""),
        "source": task["source"].as_str(),
        "taskType": task["taskType"].as_str(),
        "status": task["status"].as_str(),
        "customerId": task["customerId"].as_str(),
        "receivedAt": task["receivedAt"].as_str(),
        "dueAt": task["dueAt"].as_str(),
        "classificationState": task["classificationState"].as_str(),
        "taskMode": task["taskMode"].as_str(),
        "developerWorkflowTask": task_mcp_is_developer_task(task),
        "summary": task_mcp_summarize(summary_source, TASK_MCP_MAX_SUMMARY_LENGTH),
        "attentionState": task["attentionState"].as_str(),
        "waitingState": task["waitingState"].as_str(),
        // Authoritative planning metadata consumed by read-only integrations.
        // Keep this bounded: no full task record or source content is exposed.
        "planningBucket": task["planningBucket"].as_str(),
        "estimatedEffort": task["estimatedEffort"].as_f64(),
        "projectLabel": task["projectLabel"].as_str().or(task["customerName"].as_str()),
    });

    if workflow["currentStep"].is_string() || workflow["detectedWorkKind"].is_string() {
        result["crmWorkflow"] = serde_json::json!({
            "detectedWorkKind": workflow["detectedWorkKind"].as_str(),
            "currentStep": workflow["currentStep"].as_str(),
            "updatedAt": workflow["updatedAt"].as_str(),
        });
    }

    result
}

fn task_mcp_sanitize_comments(comments: Option<&Value>) -> Vec<Value> {
    comments
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .take(50)
        .map(|comment| {
            serde_json::json!({
                "id": comment["id"].as_str(),
                "author": comment["author"].as_str(),
                "body": task_mcp_summarize(comment["body"].as_str(), 900),
                "filePath": comment["filePath"].as_str(),
                "line": comment["line"].as_i64(),
                "isResolved": comment["isResolved"].as_bool(),
                "createdAt": comment["createdAt"].as_str(),
            })
        })
        .collect()
}

fn task_mcp_pull_request_state(workflow: &Value) -> Value {
    let proposal = workflow["pullRequestProposal"].clone();
    let tracking = workflow["pullRequestTracking"].clone();
    let review = workflow["pullRequestReview"].clone();
    let analysis = workflow["pullRequestReviewAnalysis"].clone();
    let fix_proposal = workflow["pullRequestFixProposal"].clone();
    let fix_update_tracking = workflow["pullRequestFixUpdateTracking"].clone();

    serde_json::json!({
        "proposal": if proposal.is_object() {
            serde_json::json!({
                "generatedAt": proposal["generatedAt"].as_str(),
                "title": proposal["title"].as_str(),
                "bodySummary": task_mcp_summarize(proposal["body"].as_str(), TASK_MCP_MAX_SUMMARY_LENGTH),
                "checklist": proposal["checklist"].as_array().cloned().unwrap_or_default(),
                "warnings": proposal["warnings"].as_array().cloned().unwrap_or_default(),
                "relatedArtifactPath": proposal["relatedArtifactPath"].as_str(),
                "sourceSummary": task_mcp_summarize(proposal["sourceSummary"].as_str(), 400),
                "invalidatedAt": proposal["invalidatedAt"].as_str(),
                "invalidationReason": proposal["invalidationReason"].as_str(),
            })
        } else { Value::Null },
        "tracking": if tracking.is_object() {
            serde_json::json!({
                "createdManually": tracking["createdManually"].as_bool().unwrap_or(false) && tracking["invalidatedAt"].is_null(),
                "createdAt": tracking["createdAt"].as_str(),
                "prUrl": tracking["prUrl"].as_str(),
                "notes": task_mcp_summarize(tracking["notes"].as_str(), 400),
                "invalidatedAt": tracking["invalidatedAt"].as_str(),
                "invalidationReason": tracking["invalidationReason"].as_str(),
            })
        } else { Value::Null },
        "review": if review.is_object() {
            serde_json::json!({
                "fetchedAt": review["fetchedAt"].as_str(),
                "provider": review["provider"].as_str(),
                "prUrl": review["prUrl"].as_str(),
                "title": review["title"].as_str(),
                "state": review["state"].as_str(),
                "author": review["author"].as_str(),
                "baseBranch": review["baseBranch"].as_str(),
                "headBranch": review["headBranch"].as_str(),
                "comments": task_mcp_sanitize_comments(Some(&review["comments"])),
                "unresolvedCount": review["unresolvedCount"].as_i64(),
                "attentionRequired": review["attentionRequired"].as_bool(),
                "summary": task_mcp_summarize(review["summary"].as_str(), TASK_MCP_MAX_SUMMARY_LENGTH),
                "warnings": review["warnings"].as_array().cloned().unwrap_or_default(),
                "error": task_mcp_summarize(review["error"].as_str(), 400),
                "invalidatedAt": review["invalidatedAt"].as_str(),
                "invalidationReason": review["invalidationReason"].as_str(),
            })
        } else { Value::Null },
        "analysis": if analysis.is_object() {
            serde_json::json!({
                "generatedAt": analysis["generatedAt"].as_str(),
                "sourceReviewFetchedAt": analysis["sourceReviewFetchedAt"].as_str(),
                "attentionRequired": analysis["attentionRequired"].as_bool(),
                "summary": task_mcp_summarize(analysis["summary"].as_str(), TASK_MCP_MAX_SUMMARY_LENGTH),
                "groupedFindings": analysis["groupedFindings"].as_array().cloned().unwrap_or_default(),
                "actionItems": analysis["actionItems"].as_array().cloned().unwrap_or_default(),
                "testChecklist": analysis["testChecklist"].as_array().cloned().unwrap_or_default(),
                "warnings": analysis["warnings"].as_array().cloned().unwrap_or_default(),
                "limitations": analysis["limitations"].as_array().cloned().unwrap_or_default(),
                "invalidatedAt": analysis["invalidatedAt"].as_str(),
                "invalidationReason": analysis["invalidationReason"].as_str(),
            })
        } else { Value::Null },
        "fixProposal": fix_proposal,
        "fixUpdateTracking": fix_update_tracking,
    })
}

fn task_mcp_safe_crm_workflow_state(task: &Value) -> Value {
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    if !workflow.is_object() {
        return Value::Null;
    }

    serde_json::json!({
        "detectedWorkKind": workflow["detectedWorkKind"].as_str(),
        "currentStep": workflow["currentStep"].as_str(),
        "createdAt": workflow["createdAt"].as_str(),
        "updatedAt": workflow["updatedAt"].as_str(),
        "approvals": {
            "plan": task_mcp_approval_summary(workflow.get("planApproval")),
            "diff": task_mcp_approval_summary(workflow.get("diffApproval")),
            "externalAction": task_mcp_approval_summary(workflow.get("externalActionApproval")),
            "pullRequest": task_mcp_approval_summary(workflow.get("pullRequestApproval")),
        },
        "technicalPlan": workflow["technicalPlan"].clone(),
        "externalExecution": workflow["externalExecution"].clone(),
        "pullRequest": task_mcp_pull_request_state(workflow),
    })
}

fn task_mcp_safe_task_detail(task: &Value) -> Value {
    let mut detail = task_mcp_safe_task_summary(task);
    detail["analysis"] = serde_json::json!({
        "summary": task_mcp_summarize(task["analysisResult"]["summaryEn"].as_str().or(task["analysisResult"]["summary"].as_str()), TASK_MCP_MAX_SUMMARY_LENGTH),
        "nextStep": task_mcp_summarize(task["analysisResult"]["nextStepEn"].as_str().or(task["analysisResult"]["nextStep"].as_str()), 300),
        "confidence": task["analysisResult"]["confidence"].as_f64(),
        "problemPoints": task["analysisResult"]["problemPointsEn"].as_array().cloned().or(task["analysisResult"]["problemPoints"].as_array().cloned()),
        "suggestedActions": task["analysisResult"]["suggestedActions"].as_array().cloned().unwrap_or_default(),
    });
    detail["workflowSetup"] = task["workflowSetup"].clone();
    detail["latestCrmVerification"] = task_mcp_latest_verification(task);
    detail["crmWorkflowState"] = task_mcp_safe_crm_workflow_state(task);
    detail["adoContext"] = serde_json::json!({
        "type": task["adoContext"]["type"].as_str(),
        "project": task["adoContext"]["project"].as_str(),
        "workItemId": task["adoContext"]["workItemId"].as_str(),
        "pullRequestId": task["adoContext"]["pullRequestId"].as_str(),
        "repository": task["adoContext"]["repository"].as_str(),
        "branch": task["adoContext"]["branch"].as_str(),
        "url": task["adoContext"]["url"].as_str(),
    });
    detail
}

// ── v4 packet helpers ────────────────────────────────────────────────────────

/// Returns true when the text contains a TODO/scaffold/placeholder signal or Czech
/// variants indicating field mappings have not been defined.
fn task_mcp_matches_scaffold_text(text: &str) -> bool {
    let lower = text.to_lowercase();
    if lower.contains("todo") || lower.contains("scaffold") || lower.contains("placeholder") {
        return true;
    }
    if lower.contains("field mappings are not defined")
        || lower.contains("field mappings not defined")
        || lower.contains("define field mappings")
    {
        return true;
    }
    // Czech variants
    if lower.contains("field mappings nejsou definov") {
        return true;
    }
    if lower.contains("mapov")
        && (lower.contains("doplnit") || lower.contains("mus") && lower.contains("dopl"))
    {
        return true;
    }
    if lower.contains("doplnění") && lower.contains("field mapping") {
        return true;
    }
    if lower.contains("připravit todo") || lower.contains("pripravi todo") {
        return true;
    }
    false
}

/// Returns true when the packet has the concrete trusted data needed to safely replace
/// stale scaffold plan steps/risks with deterministic steps derived from the work packet.
///
/// Called only when the safety check returned exactly one reason (the TODO/scaffold text
/// reason). All other safety conditions (external actions, trusted source, scaffoldOnly,
/// etc.) were already verified by the safety check returning a single reason, but the
/// packet-level conditions below are double-checked for belt-and-suspenders safety.
fn task_mcp_can_safely_refresh_plan(packet: &Value) -> bool {
    let impl_obj = &packet["implementation"];
    let write_tgt = &packet["writeTarget"];

    // Field mappings must be non-empty and from a trusted source.
    let fm_count = impl_obj["fieldMappings"]
        .as_array()
        .map(|a| a.len())
        .unwrap_or(0);
    if fm_count == 0 {
        return false;
    }
    let fm_source = impl_obj["fieldMappingsSource"].as_str().unwrap_or("none");
    if !matches!(fm_source, "template" | "plan") {
        return false;
    }

    // Packet must not flag scaffoldOnly or finalConsistencyGuardApplied.
    if impl_obj["scaffoldOnly"].as_bool().unwrap_or(true) {
        return false;
    }
    if impl_obj["finalConsistencyGuardApplied"]
        .as_bool()
        .unwrap_or(true)
    {
        return false;
    }

    // writeTarget must have the concrete values required to generate steps.
    if write_tgt["artifactPath"]
        .as_str()
        .filter(|s| !s.is_empty())
        .is_none()
    {
        return false;
    }
    if write_tgt["targetEntity"]
        .as_str()
        .filter(|s| !s.is_empty())
        .is_none()
    {
        return false;
    }

    true
}

/// Generates concrete, deterministic implementation steps from a trusted work packet.
/// Used by the safe plan refresh path to replace stale scaffold/TODO steps.
fn task_mcp_generate_concrete_steps_from_packet(packet: &Value) -> Vec<Value> {
    let write_tgt = &packet["writeTarget"];
    let impl_obj = &packet["implementation"];
    let field_mappings = impl_obj["fieldMappings"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let validation_fields = impl_obj["validationFields"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let work_kind = write_tgt["kind"].as_str().unwrap_or("");
    let mut steps: Vec<Value> = Vec::new();

    if work_kind == "script" || work_kind == "ribbon" {
        // 1. File action
        if let Some(ap) = write_tgt["artifactPath"].as_str().filter(|s| !s.is_empty()) {
            steps.push(serde_json::json!(format!("Create or update {}.", ap)));
        }
        // 2. Handler registration
        let on_load = write_tgt["handlers"]["onLoad"].as_str().unwrap_or("");
        let on_change = write_tgt["handlers"]["onChange"].as_str().unwrap_or("");
        match (!on_load.is_empty(), !on_change.is_empty()) {
            (true, true) => steps.push(serde_json::json!(format!(
                "Register/prepare handlers {} and {}.",
                on_load, on_change
            ))),
            (true, false) => steps.push(serde_json::json!(format!(
                "Register/prepare handler {}.",
                on_load
            ))),
            _ => {}
        }
        // 3. Retrieve source entity on event field change
        let event_field = write_tgt["eventFieldName"].as_str().unwrap_or("");
        if !event_field.is_empty() {
            let source_entity = field_mappings
                .first()
                .and_then(|m| m["source"].as_str())
                .and_then(|s| s.split('.').next())
                .unwrap_or("source");
            steps.push(serde_json::json!(format!(
                "On {} change, retrieve {} using Xrm.WebApi.retrieveRecord.",
                event_field, source_entity
            )));
        }
        // 4. Copy field mappings
        for m in &field_mappings {
            if let (Some(src), Some(tgt)) = (m["source"].as_str(), m["target"].as_str()) {
                steps.push(serde_json::json!(format!("Copy {} to {}.", src, tgt)));
            }
        }
        // 5. Validation-only fields
        for vf in &validation_fields {
            if let Some(s) = vf.as_str() {
                steps.push(serde_json::json!(format!(
                    "Use {} only as validation source for conditional logic.",
                    s
                )));
            }
        }
        // 6. No-auto-save / no-upload guardrails
        steps.push(serde_json::json!("Do not auto-save the form."));
        steps.push(serde_json::json!(
            "Do not upload/register the web resource automatically."
        ));
    } else {
        // Plugin
        let artifact = write_tgt["artifactPath"]
            .as_str()
            .or_else(|| write_tgt["pluginProject"].as_str())
            .unwrap_or("");
        if !artifact.is_empty() {
            steps.push(serde_json::json!(format!(
                "Create or update the plugin class in {}.",
                artifact
            )));
        }
        let message = write_tgt["message"].as_str().unwrap_or("");
        let stage = write_tgt["stage"].as_str().unwrap_or("");
        let target_entity = write_tgt["targetEntity"].as_str().unwrap_or("");
        if !message.is_empty() && !stage.is_empty() && !target_entity.is_empty() {
            steps.push(serde_json::json!(format!(
                "Register handler for {} {} on {}.",
                message, stage, target_entity
            )));
        }
        for m in &field_mappings {
            if let (Some(src), Some(tgt)) = (m["source"].as_str(), m["target"].as_str()) {
                steps.push(serde_json::json!(format!("Set {} from {}.", tgt, src)));
            }
        }
    }

    steps
}

/// Returns true if `word` (expected already lowercased) looks like a CRM logical name.
/// Pattern: 3–5 lowercase-letter publisher prefix + `_` + ≥3-char lowercase/digit/`_` suffix.
/// The 3-char minimum on the prefix avoids false positives from common 2-letter English words
/// like "is", "on", "no" that would otherwise match the publisher-prefix shape.
fn task_mcp_looks_like_crm_name(word: &str) -> bool {
    let Some(first_us) = word.find('_') else {
        return false;
    };
    if first_us < 3 || first_us > 5 {
        return false;
    }
    if first_us + 1 >= word.len() {
        return false;
    }
    let prefix = &word[..first_us];
    let suffix = &word[first_us + 1..];
    if !prefix.chars().all(|c| c.is_ascii_lowercase()) {
        return false;
    }
    if suffix.len() < 3 {
        return false;
    }
    if !suffix
        .chars()
        .next()
        .map(|c| c.is_ascii_lowercase())
        .unwrap_or(false)
    {
        return false;
    }
    suffix
        .chars()
        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
}

/// Builds the set of logical names (entities and fields) that are trusted in the given work packet.
/// Includes: target entity, event field name, entity/field parts from fieldMappings and validationFields.
fn task_mcp_build_allowed_logical_names(packet: &Value) -> std::collections::HashSet<String> {
    let mut allowed = std::collections::HashSet::<String>::new();
    let impl_obj = &packet["implementation"];
    let write_tgt = &packet["writeTarget"];

    fn add_dotted(set: &mut std::collections::HashSet<String>, s: &str) {
        let lower = s.to_lowercase();
        set.insert(lower.clone());
        if let Some(dot) = lower.find('.') {
            set.insert(lower[..dot].to_string());
            set.insert(lower[dot + 1..].to_string());
        }
    }

    if let Some(s) = write_tgt["targetEntity"].as_str().filter(|s| !s.is_empty()) {
        allowed.insert(s.to_lowercase());
    }
    // eventFieldName is a field name (e.g. nvr_assetid), not an entity name — still add it so
    // risks that legitimately mention the trigger field are not incorrectly removed.
    if let Some(s) = write_tgt["eventFieldName"]
        .as_str()
        .filter(|s| !s.is_empty())
    {
        allowed.insert(s.to_lowercase());
    }
    if let Some(mappings) = impl_obj["fieldMappings"].as_array() {
        for m in mappings {
            for key in ["source", "target"] {
                if let Some(s) = m[key].as_str().filter(|s| !s.is_empty()) {
                    add_dotted(&mut allowed, s);
                }
            }
        }
    }
    if let Some(vfs) = impl_obj["validationFields"].as_array() {
        for vf in vfs {
            if let Some(s) = vf.as_str().filter(|s| !s.is_empty()) {
                add_dotted(&mut allowed, s);
            }
        }
    }
    allowed
}

/// Returns `true` if `risk_text` contains a CRM-style logical name that is **not** in `allowed`.
/// Used to filter risks that mention hallucinated or stale entity/field names not present in the
/// trusted work packet.
fn task_mcp_risk_mentions_unknown_entity(
    risk_text: &str,
    allowed: &std::collections::HashSet<String>,
) -> bool {
    let lower = risk_text.to_lowercase();
    let mut word_start: Option<usize> = None;
    for (byte_pos, ch) in lower.char_indices() {
        if ch.is_ascii_alphanumeric() || ch == '_' {
            if word_start.is_none() {
                word_start = Some(byte_pos);
            }
        } else if let Some(start) = word_start.take() {
            let word = &lower[start..byte_pos];
            if task_mcp_looks_like_crm_name(word) && !allowed.contains(word) {
                return true;
            }
        }
    }
    // Handle a word that runs to the end of the string.
    if let Some(start) = word_start {
        let word = &lower[start..];
        if task_mcp_looks_like_crm_name(word) && !allowed.contains(word) {
            return true;
        }
    }
    false
}

/// Returns the cleaned risks for a refreshed plan: removes scaffold/TODO risks from
/// `existing_risks`, also removes risks that mention CRM entity names not present in the
/// trusted packet (to eliminate hallucinated/stale entity references), and appends standard
/// guardrail risks for the work kind if not already present.
fn task_mcp_generate_clean_risks_from_packet(
    existing_risks: &[Value],
    packet: &Value,
) -> Vec<Value> {
    let work_kind = packet["writeTarget"]["kind"].as_str().unwrap_or("");
    let allowed = task_mcp_build_allowed_logical_names(packet);

    // Preserve risks that contain neither scaffold/TODO text nor unknown CRM entity names.
    let mut risks: Vec<Value> = existing_risks
        .iter()
        .filter(|v| {
            let t = v
                .as_str()
                .map(str::to_string)
                .unwrap_or_else(|| v.to_string());
            !task_mcp_matches_scaffold_text(&t)
                && !task_mcp_risk_mentions_unknown_entity(&t, &allowed)
        })
        .cloned()
        .collect();

    // Append standard guardrail risks if not already present.
    let standard: &[&str] = if work_kind == "script" || work_kind == "ribbon" {
        &[
            "Dataverse metadata must be verified in-app for JS/TS.",
            "Web resource upload and form registration are manual/approval-gated steps.",
        ]
    } else {
        &["Plugin registration is a manual approval-gated step."]
    };
    for &risk in standard {
        let already = risks
            .iter()
            .any(|r| r.as_str().map(|s| s.contains(risk)).unwrap_or(false));
        if !already {
            risks.push(serde_json::json!(risk));
        }
    }

    risks
}

/// Check whether a candidate string looks like `entity.field` where both parts are
/// CRM-style logical names (underscore-separated lowercase alphanumeric).
fn task_mcp_is_valid_crm_dotted(s: &str) -> bool {
    let Some(dot) = s.find('.') else {
        return false;
    };
    let entity = &s[..dot];
    let field = &s[dot + 1..];
    let valid_part = |p: &str| -> bool {
        if p.len() < 2 {
            return false;
        }
        p.chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
            && p.chars()
                .next()
                .map(|c| c.is_ascii_lowercase())
                .unwrap_or(false)
            && p.contains('_')
    };
    valid_part(entity) && valid_part(field)
}

/// Extract `entity.field` token ending just before `end_pos` in `text`.
fn task_mcp_extract_left_dotted(text: &str) -> Option<String> {
    let text = text.trim_end();
    let bytes = text.as_bytes();
    let mut i = bytes.len();
    while i > 0 {
        let c = bytes[i - 1];
        if c.is_ascii_alphanumeric() || c == b'_' || c == b'.' {
            i -= 1;
        } else {
            break;
        }
    }
    let token = &text[i..];
    if token.contains('.') {
        Some(token.to_lowercase())
    } else {
        None
    }
}

/// Extract `entity.field` token starting at the beginning of `text`.
fn task_mcp_extract_right_dotted(text: &str) -> Option<String> {
    let text = text.trim_start();
    let mut end = 0;
    let bytes = text.as_bytes();
    while end < bytes.len() {
        let c = bytes[end];
        if c.is_ascii_alphanumeric() || c == b'_' || c == b'.' {
            end += 1;
        } else {
            break;
        }
    }
    let token = &text[..end];
    if token.contains('.') {
        Some(token.to_lowercase())
    } else {
        None
    }
}

/// Count distinct CRM-style logical names (`prefix_suffix` pattern) in text.
fn task_mcp_count_crm_names(text: &str) -> usize {
    let mut names = std::collections::HashSet::new();
    for word in text.split(|c: char| !c.is_ascii_alphanumeric() && c != '_') {
        let word = word.to_lowercase();
        if word.len() < 4 {
            continue;
        }
        if !word.contains('_') {
            continue;
        }
        let first = word.chars().next().unwrap_or(' ');
        if !first.is_ascii_lowercase() {
            continue;
        }
        // Must have at least one segment before and after the underscore
        let underscore = word.find('_').unwrap_or(0);
        if underscore == 0 || underscore == word.len() - 1 {
            continue;
        }
        if word
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
        {
            names.insert(word);
        }
    }
    names.len()
}

/// Port of JS detectAndExtractFieldMappings.
/// Returns (required, mappings, validation_fields, sources).
fn task_mcp_detect_field_mappings(task: &Value) -> (bool, Vec<Value>, Vec<Value>, Vec<String>) {
    let strip_html = |s: &str| -> String {
        let mut out = String::with_capacity(s.len());
        let mut in_tag = false;
        for c in s.chars() {
            if c == '<' {
                in_tag = true;
                out.push(' ');
            } else if c == '>' {
                if !in_tag {
                    out.push(c);
                }
                in_tag = false;
            } else if !in_tag {
                out.push(c);
            }
        }
        out
    };

    let workflow = &task["crmDeveloperWorkflow"];
    let plan = &workflow["technicalPlan"];

    let join_array = |v: &Value| -> String {
        v.as_array()
            .map(|arr| {
                arr.iter()
                    .map(|x| {
                        x.as_str().unwrap_or_else(|| {
                            x["description"]
                                .as_str()
                                .or_else(|| x["step"].as_str())
                                .or_else(|| x["risk"].as_str())
                                .unwrap_or("")
                        })
                    })
                    .collect::<Vec<_>>()
                    .join("\n")
            })
            .unwrap_or_default()
    };

    let text_parts: Vec<(&str, String)> = vec![
        (
            "originalMessage",
            strip_html(task["originalMessage"].as_str().unwrap_or("")),
        ),
        (
            "description",
            strip_html(task["description"].as_str().unwrap_or("")),
        ),
        (
            "analysisEn",
            strip_html(task["analysisResult"]["summaryEn"].as_str().unwrap_or("")),
        ),
        (
            "analysis",
            strip_html(task["analysisResult"]["summary"].as_str().unwrap_or("")),
        ),
        (
            "requirements",
            join_array(&task["analysisResult"]["requirements"]),
        ),
        (
            "planSummary",
            strip_html(plan["summary"].as_str().unwrap_or("")),
        ),
        ("planSteps", join_array(&plan["implementationSteps"])),
        ("planRisks", join_array(&plan["risks"])),
    ];

    let sources: Vec<String> = text_parts
        .iter()
        .filter(|(_, v)| !v.trim().is_empty())
        .map(|(k, _)| k.to_string())
        .collect();

    let raw_text: String = text_parts
        .iter()
        .map(|(_, v)| v.as_str())
        .collect::<Vec<_>>()
        .join("\n");
    let raw_text = raw_text.trim();
    if raw_text.is_empty() {
        return (false, vec![], vec![], sources);
    }

    // Detect source/target entity context
    let lower = raw_text.to_lowercase();
    let has_source_context = lower.contains("source entit")
        || lower.contains("src entit")
        || (lower.contains("zdrojov") && lower.contains("entit"))
        || lower.contains("zdroj:");
    let has_target_context = lower.contains("target entit")
        || lower.contains("destination entit")
        || (lower.contains("cílov") && lower.contains("entit"))
        || (lower.contains("cilova") && lower.contains("entit"))
        || lower.contains("cíl:")
        || lower.contains("cil:");

    let crm_count = task_mcp_count_crm_names(&lower);

    // Detect when plan text signals incomplete field mapping work
    let plan_signals_incomplete = crm_count >= 2
        && (lower.contains("field mappings are not defined")
            || lower.contains("define field mappings")
            || lower.contains("field mappings not defined")
            || lower.contains("field mappings nejsou definov")
            || (lower.contains("mapov") && lower.contains("dopl") && crm_count >= 2)
            || lower.contains("doplnění") && lower.contains("field mapping")
            || lower.contains("připravit todo")
            || lower.contains("pripravi todo")
            || (lower.contains("todo") && lower.contains("map") && lower.contains("field"))
            || (lower.contains("field") && lower.contains("map") && lower.contains("todo")));

    let detected =
        ((has_source_context || has_target_context) && crm_count >= 3) || plan_signals_incomplete;
    if !detected {
        return (false, vec![], vec![], sources);
    }

    // Extraction attempt 1: entity.field -> entity.field arrows
    let mut arrow_mappings: Vec<Value> = Vec::new();
    let mut arrow_seen = std::collections::HashSet::new();
    for sep in &["->", "→", "=>"] {
        let mut search_pos = 0usize;
        while let Some(rel) = lower[search_pos..].find(sep) {
            let abs_pos = search_pos + rel;
            let left = task_mcp_extract_left_dotted(&lower[..abs_pos]);
            let right = task_mcp_extract_right_dotted(&lower[abs_pos + sep.len()..]);
            if let (Some(l), Some(r)) = (left, right) {
                if task_mcp_is_valid_crm_dotted(&l) && task_mcp_is_valid_crm_dotted(&r) {
                    let key = format!("{}=>{}", l, r);
                    if !arrow_seen.contains(&key) {
                        arrow_seen.insert(key);
                        arrow_mappings.push(serde_json::json!({"source": l, "target": r}));
                    }
                }
            }
            search_pos = abs_pos + sep.len();
        }
    }
    if arrow_mappings.len() >= 2 {
        return (true, arrow_mappings, vec![], sources);
    }

    // Extraction attempt 2: Source entity/fields / Target entity/fields block
    let src_entity = find_pattern_after(
        &lower,
        &[
            "source entity:",
            "source entity :",
            "zdrojová entita:",
            "zdrojova entita:",
            "zdroj:",
        ],
    );
    let tgt_entity = find_pattern_after(
        &lower,
        &[
            "target entity:",
            "target entity :",
            "cílová entita:",
            "cilova entita:",
            "cíl:",
            "cil:",
        ],
    );
    let src_fields_str = find_pattern_after(
        &lower,
        &[
            "source fields:",
            "source field:",
            "zdrojová pole:",
            "zdrojova pole:",
            "pole zdroje:",
            "copy fields:",
            "fields:",
        ],
    );
    let tgt_fields_str = find_pattern_after(
        &lower,
        &[
            "target fields:",
            "target field:",
            "cílová pole:",
            "cilova pole:",
            "pole cíle:",
            "pole cile:",
        ],
    );

    if let (Some(se), Some(te), Some(sfs), Some(tfs)) =
        (src_entity, tgt_entity, src_fields_str, tgt_fields_str)
    {
        let parse_fields = |s: &str| -> Vec<String> {
            s.split(|c: char| !c.is_ascii_alphanumeric() && c != '_')
                .map(str::trim)
                .filter(|f| {
                    f.len() > 2
                        && f.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
                        && f.contains('_')
                })
                .map(|f| f.to_lowercase())
                .collect()
        };
        let sf: Vec<String> = parse_fields(sfs.split('\n').next().unwrap_or(""));
        let tf: Vec<String> = parse_fields(tfs.split('\n').next().unwrap_or(""));
        if sf.len() >= 2 && tf.len() >= 2 {
            let pair_count = sf.len().min(tf.len());
            let mappings: Vec<Value> = (0..pair_count)
                .map(|i| serde_json::json!({"source": format!("{}.{}", se.trim(), sf[i]), "target": format!("{}.{}", te.trim(), tf[i])}))
                .collect();
            let validation_fields: Vec<Value> = sf[pair_count..]
                .iter()
                .map(|f| serde_json::json!(format!("{}.{}", se.trim(), f)))
                .collect();
            return (true, mappings, validation_fields, sources);
        }
    }

    // Detected but could not safely extract pairs
    (true, vec![], vec![], sources)
}

/// Find the first line of text after one of the given prefixes (case-insensitive, already lowercased input).
fn find_pattern_after<'a>(lower: &'a str, prefixes: &[&str]) -> Option<&'a str> {
    for prefix in prefixes {
        if let Some(pos) = lower.find(prefix) {
            let after = &lower[pos + prefix.len()..];
            let trimmed = after.trim_start_matches(|c: char| c == ' ' || c == '\t');
            if !trimmed.is_empty() {
                return Some(trimmed);
            }
        }
    }
    None
}

const DEVELOPER_WORK_PACKET_VERSION: &str = "4";

fn task_mcp_developer_work_packet(
    task: &Value,
    customer_dev_defaults: Option<&Value>,
    ai_kit_path: Option<&str>,
) -> Value {
    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let plan = &workflow["technicalPlan"];
    let plan_target = &plan["target"];
    let readiness = task_mcp_implementation_readiness(task);
    let template = task_mcp_match_template(
        task["title"].as_str().unwrap_or(""),
        &task_mcp_task_text_for_inference(task),
    );
    let work_kind = workflow["detectedWorkKind"]
        .as_str()
        .or_else(|| setup["devTargetKind"].as_str())
        .or_else(|| plan["workKind"].as_str())
        .unwrap_or("unknown");
    let is_script = work_kind == "script"
        || work_kind == "ribbon"
        || setup["devTargetKind"].as_str() == Some("script");
    let script_naming = if is_script {
        task_mcp_compute_script_naming(task, customer_dev_defaults)
    } else {
        None
    };
    let verification = task_mcp_latest_verification(task);
    let approval = task_mcp_approval_summary(workflow.get("planApproval"));
    let next = task_mcp_next_recommended_step(task);

    // ── Field mapping detection (four paths, matching JS v4 logic) ──────────
    let plan_field_mappings = plan["fieldMappings"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let empty_field_mappings = plan_field_mappings.is_empty();

    let template_needs_mapping = template
        .as_ref()
        .map(|t| {
            t["sourceFields"]
                .as_array()
                .map(|a| !a.is_empty())
                .unwrap_or(false)
        })
        .unwrap_or(false);

    let plan_has_unmapped_with_no_mapped = {
        let unmapped = plan["unmappedSourceFields"]
            .as_array()
            .map(|a| !a.is_empty())
            .unwrap_or(false);
        unmapped && empty_field_mappings
    };

    // Template path: auto-derive fieldMappings from template sourceFields/targetFields when plan is empty
    let template_field_mappings: Vec<Value> =
        if template_needs_mapping && plan_field_mappings.is_empty() {
            template
                .as_ref()
                .map(|tpl| {
                    let src_entity = tpl["sourceEntity"].as_str().unwrap_or("");
                    let tgt_entity = tpl["targetEntity"]
                        .as_str()
                        .or_else(|| setup["primaryEntityLogicalName"].as_str())
                        .or_else(|| plan_target["entityLogicalName"].as_str())
                        .unwrap_or("");
                    if src_entity.is_empty() || tgt_entity.is_empty() {
                        return vec![];
                    }
                    let src_fields: Vec<&str> = tpl["sourceFields"]
                        .as_array()
                        .map(|a| a.iter().filter_map(|v| v.as_str()).collect())
                        .unwrap_or_default();
                    let tgt_fields: Vec<&str> = tpl["targetFields"]
                        .as_array()
                        .map(|a| a.iter().filter_map(|v| v.as_str()).collect())
                        .unwrap_or_default();
                    let pair_count = src_fields.len().min(tgt_fields.len());
                    (0..pair_count)
                        .map(|i| {
                            serde_json::json!({
                                "source": format!("{}.{}", src_entity, src_fields[i]),
                                "target": format!("{}.{}", tgt_entity, tgt_fields[i])
                            })
                        })
                        .collect()
                })
                .unwrap_or_default()
        } else {
            vec![]
        };

    // Text extraction path (only when template and plan don't already signal mapping work)
    let (
        text_detected_required,
        text_extracted_mappings,
        text_extracted_validation,
        text_detection_sources,
    ) = if empty_field_mappings && !template_needs_mapping && !plan_has_unmapped_with_no_mapped {
        task_mcp_detect_field_mappings(task)
    } else {
        (false, vec![], vec![], vec![])
    };

    // Script implementation pattern: 'field-mapping' (source→target copy/prefill, needs
    // fieldMappings), 'ui-business-rule' (form UI logic — required level, visibility,
    // notifications, locking, option filtering — no fieldMappings by design), or
    // 'ribbon-action'. workflowSetup override wins over the template. Mirrors
    // mcp/task-workbench-mcp.mjs buildDeveloperWorkPacket — keep in sync.
    let implementation_pattern: Option<String> = setup["implementationPattern"]
        .as_str()
        .map(str::to_string)
        .or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["implementationPattern"].as_str())
                .map(str::to_string)
        })
        .or_else(|| {
            if template_needs_mapping {
                Some("field-mapping".to_string())
            } else {
                None
            }
        });
    let is_non_mapping_pattern = matches!(
        implementation_pattern.as_deref(),
        Some("ui-business-rule") | Some("ribbon-action")
    );
    // An explicit requiresFieldMappings (workflowSetup override, then template) is authoritative:
    // it overrides the heuristic signals below in both directions — a stale
    // plan.unmappedSourceFields left over from an earlier save must not force a UI/business-rule
    // script with no field-mapping needs to be misread as requiring mappings.
    let explicit_requires_field_mappings: Option<bool> =
        setup["requiresFieldMappings"].as_bool().or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["requiresFieldMappings"].as_bool())
        });
    let heuristic_requires_field_mappings =
        template_needs_mapping || plan_has_unmapped_with_no_mapped || text_detected_required;
    let requires_field_mappings = if is_non_mapping_pattern {
        false
    } else {
        explicit_requires_field_mappings.unwrap_or(heuristic_requires_field_mappings)
    };
    // UI/business-rule and ribbon-action script context — workflowSetup (persisted by
    // prepare_developer_task when a template applies) wins over the template, so these survive
    // even once the task text no longer re-matches the template that originally set them.
    let referenced_fields: Vec<Value> = setup["referencedFields"]
        .as_array()
        .cloned()
        .or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["referencedFields"].as_array().cloned())
        })
        .unwrap_or_default();
    let trigger_fields: Vec<Value> = setup["triggerFields"]
        .as_array()
        .cloned()
        .or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["triggerFields"].as_array().cloned())
        })
        .unwrap_or_default();
    let affected_fields: Vec<Value> = setup["affectedFields"]
        .as_array()
        .cloned()
        .or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["affectedFields"].as_array().cloned())
        })
        .unwrap_or_default();
    let ui_rules: Vec<Value> = setup["uiRules"]
        .as_array()
        .cloned()
        .or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["uiRules"].as_array().cloned())
        })
        .unwrap_or_default();
    let option_set_values: Value = if setup["optionSetValues"].is_object() {
        setup["optionSetValues"].clone()
    } else if let Some(t) = &template {
        if t["optionSetValues"].is_object() {
            t["optionSetValues"].clone()
        } else {
            serde_json::json!({})
        }
    } else {
        serde_json::json!({})
    };
    let notification_ids: Vec<Value> = setup["notificationIds"]
        .as_array()
        .cloned()
        .or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["notificationIds"].as_array().cloned())
        })
        .unwrap_or_default();
    let forbidden_operations: Vec<Value> = setup["forbiddenOperations"]
        .as_array()
        .cloned()
        .or_else(|| {
            template
                .as_ref()
                .and_then(|t| t["forbiddenOperations"].as_array().cloned())
        })
        .unwrap_or_default();

    let field_mappings_missing = requires_field_mappings
        && empty_field_mappings
        && text_extracted_mappings.is_empty()
        && template_field_mappings.is_empty();

    let plan_approval_required =
        plan.is_object() && !approval["approved"].as_bool().unwrap_or(false);
    let readiness_ready = readiness["isImplementationReady"]
        .as_bool()
        .unwrap_or(false);

    let mut can_write = readiness_ready && !plan_approval_required && !field_mappings_missing;

    let blockers: Vec<Value> = readiness["blockers"]
        .as_array()
        .cloned()
        .unwrap_or_default();

    let mut decision_reason;
    let mut blocking_user_action = Value::Null;

    if can_write {
        decision_reason =
            "Task Workbench says implementation is ready. Use this packet as the working contract."
                .to_string();
    } else if plan_approval_required {
        decision_reason =
            "Technical plan approval is required in Task Workbench before code changes."
                .to_string();
        blocking_user_action = serde_json::json!(
            "Review and approve the technical implementation plan in Task Workbench."
        );
    } else if field_mappings_missing {
        decision_reason = if text_detected_required {
            "Field mapping work is indicated in the original assignment but field mappings have not been defined in the technical plan. Complete the technical plan before implementation.".to_string()
        } else {
            "Field mappings are missing. Complete the technical plan before implementation."
                .to_string()
        };
        blocking_user_action = serde_json::json!(
            "Run prepare_developer_task to regenerate the technical plan with field mappings."
        );
    } else {
        decision_reason = blockers
            .first()
            .and_then(|b| b.as_str())
            .or_else(|| readiness["recommendedNextStep"].as_str())
            .unwrap_or("Task Workbench says implementation is not ready yet.")
            .to_string();
        if !plan.is_object() {
            blocking_user_action = serde_json::json!(
                "Run prepare_developer_task to create/refresh setup and the technical plan."
            );
        } else if blockers
            .first()
            .and_then(|b| b.as_str())
            .map(|s| s.contains("has not been saved to task setup"))
            .unwrap_or(false)
        {
            blocking_user_action = serde_json::json!("Run prepare_developer_task or call set_task_developer_target to save the target path.");
        } else if !blockers.is_empty() {
            blocking_user_action =
                serde_json::json!("Resolve the listed blockers in Task Workbench.");
        }
    }

    // ── Guard 1: requiresFieldMappings consistency ───────────────────────────
    // Priority: text-extracted > template-derived > plan
    let final_field_mappings: Vec<Value> = if !text_extracted_mappings.is_empty() {
        text_extracted_mappings.clone()
    } else if !template_field_mappings.is_empty() {
        template_field_mappings.clone()
    } else {
        plan_field_mappings.clone()
    };
    if requires_field_mappings && final_field_mappings.is_empty() && can_write {
        can_write = false;
        decision_reason = "Required field mappings are missing. Packet consistency guard blocked code writing. The task requires source\u{2192}target field assignments that have not been defined.".to_string();
        blocking_user_action = serde_json::json!("Define source\u{2192}target field mappings in the technical plan using prepare_developer_task or save_technical_plan.");
    }

    // ── Guard 2: scaffold signal detection (diagnostic) ──────────────────────
    let mut scaffold_signal_detected = false;
    let mut scaffold_signal_sources: Vec<Value> = Vec::new();
    let raw_steps: Vec<Value> = plan["implementationSteps"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let raw_risks: Vec<Value> = plan["risks"].as_array().cloned().unwrap_or_default();
    if can_write && final_field_mappings.is_empty() {
        let check_texts: Vec<String> = raw_steps
            .iter()
            .chain(raw_risks.iter())
            .map(|v| {
                v.as_str()
                    .map(str::to_string)
                    .unwrap_or_else(|| v.to_string())
            })
            .chain(std::iter::once(
                plan["summary"].as_str().unwrap_or("").to_string(),
            ))
            .collect();
        let signals: Vec<Value> = check_texts
            .into_iter()
            .filter(|t| task_mcp_matches_scaffold_text(t))
            .map(Value::String)
            .collect();
        if !signals.is_empty() {
            scaffold_signal_detected = true;
            scaffold_signal_sources = signals;
        }
    }

    // ── Sanitize scaffold steps/risks when mappings are available ─────────────
    let sanitized_steps: Vec<Value> = if can_write && !final_field_mappings.is_empty() {
        raw_steps
            .iter()
            .filter(|v| {
                let text = v
                    .as_str()
                    .map(str::to_string)
                    .unwrap_or_else(|| v.to_string());
                !task_mcp_matches_scaffold_text(&text)
            })
            .cloned()
            .collect()
    } else {
        raw_steps.clone()
    };
    let sanitized_risks: Vec<Value> = if can_write && !final_field_mappings.is_empty() {
        raw_risks
            .iter()
            .filter(|v| {
                let text = v
                    .as_str()
                    .map(str::to_string)
                    .unwrap_or_else(|| v.to_string());
                !task_mcp_matches_scaffold_text(&text)
            })
            .cloned()
            .collect()
    } else {
        raw_risks.clone()
    };

    // ── Final packet invariant ────────────────────────────────────────────────
    let mut final_consistency_guard_applied = false;
    if can_write && final_field_mappings.is_empty() {
        let packet_has_scaffold = sanitized_steps
            .iter()
            .chain(sanitized_risks.iter())
            .any(|v| {
                let text = v
                    .as_str()
                    .map(str::to_string)
                    .unwrap_or_else(|| v.to_string());
                task_mcp_matches_scaffold_text(&text)
            });
        if packet_has_scaffold {
            final_consistency_guard_applied = true;
            can_write = false;
            decision_reason = "Packet invariant violation: implementation steps or risks contain TODO/scaffold/placeholder guidance while field mappings are empty. Required source\u{2192}target field assignments must be defined before code can be written.".to_string();
            blocking_user_action = serde_json::json!("Define source\u{2192}target field mappings in the technical plan using prepare_developer_task or save_technical_plan.");
        }
    }

    // ── Write target ──────────────────────────────────────────────────────────
    let target_entity = setup["primaryEntityLogicalName"]
        .as_str()
        .or_else(|| plan_target["entityLogicalName"].as_str())
        .or_else(|| template.as_ref().and_then(|t| t["targetEntity"].as_str()));
    let repository_root = setup["repositoryRoot"]
        .as_str()
        .or_else(|| customer_dev_defaults.and_then(|d| d["repositoryRoot"].as_str()));

    let write_target = if is_script {
        serde_json::json!({
            "kind": "script",
            "repositoryRoot": repository_root,
            "artifactPath": setup["artifactPath"].as_str()
                .or_else(|| setup["scriptPath"].as_str())
                .or_else(|| plan_target["scriptPath"].as_str())
                .or_else(|| script_naming.as_ref().and_then(|n| n["scriptPath"].as_str())),
            "absolutePath": setup["absoluteScriptPath"].as_str()
                .or_else(|| script_naming.as_ref().and_then(|n| n["absoluteScriptPath"].as_str())),
            "targetEntity": target_entity,
            "actionType": setup["actionType"].as_str()
                .or_else(|| template.as_ref().and_then(|t| t["actionType"].as_str())),
            "eventName": setup["eventName"].as_str()
                .or_else(|| plan_target["eventName"].as_str())
                .or_else(|| template.as_ref().and_then(|t| t["scriptTarget"]["eventName"].as_str())),
            "eventFieldName": setup["eventFieldName"].as_str()
                .or_else(|| plan_target["eventFieldName"].as_str())
                .or_else(|| template.as_ref().and_then(|t| t["scriptTarget"]["eventFieldName"].as_str())),
            "handlers": {
                "onLoad": setup["onLoadFunctionName"].as_str()
                    .or_else(|| script_naming.as_ref().and_then(|n| n["onLoadFunctionName"].as_str())),
                "onChange": setup["onChangeFunctionName"].as_str()
                    .or_else(|| script_naming.as_ref().and_then(|n| n["onChangeFunctionName"].as_str())),
            },
            "helperSuggestion": setup["mainHelperSuggestion"].as_str()
                .or_else(|| script_naming.as_ref().and_then(|n| n["mainHelperSuggestion"].as_str())),
        })
    } else {
        serde_json::json!({
            "kind": if work_kind == "plugin" { "plugin" } else { work_kind },
            "repositoryRoot": repository_root,
            "artifactPath": setup["pluginProject"].as_str().or_else(|| plan_target["pluginProject"].as_str()),
            "targetEntity": target_entity,
            "actionType": setup["actionType"].as_str()
                .or_else(|| template.as_ref().and_then(|t| t["actionType"].as_str())),
            "pluginProject": setup["pluginProject"].as_str().or_else(|| plan_target["pluginProject"].as_str()),
            "message": plan_target["message"].as_str()
                .or_else(|| template.as_ref().and_then(|t| t["pluginTarget"]["messages"].as_array().and_then(|a| a.first()).and_then(|v| v.as_str()))),
            "stage": plan_target["stage"].as_str()
                .or_else(|| template.as_ref().and_then(|t| t["pluginTarget"]["stage"].as_str())),
            "mode": plan_target["mode"].as_str()
                .or_else(|| template.as_ref().and_then(|t| t["pluginTarget"]["mode"].as_str())),
            "filteringAttributes": plan_target["filteringAttributes"].as_array().cloned().unwrap_or_default(),
        })
    };

    // ── Conventions ───────────────────────────────────────────────────────────
    let mut convention_sources: Vec<Value> = Vec::new();
    if let Some(v) = setup["conventionsSource"]
        .as_str()
        .filter(|s| !s.is_empty())
    {
        convention_sources.push(serde_json::json!(v));
    }
    if let Some(defaults) = customer_dev_defaults {
        let key = if is_script {
            "jsConventionsSource"
        } else {
            "pluginConventionsSource"
        };
        if let Some(v) = defaults[key].as_str().filter(|s| !s.is_empty()) {
            convention_sources.push(serde_json::json!(v));
        }
    }
    let convention_rules: Vec<Value> = if is_script {
        vec![
            serde_json::json!("Inspect existing form scripts before editing."),
            serde_json::json!("Use the handler/helper names from writeTarget."),
            serde_json::json!("Do not register or upload web resources from MCP."),
        ]
    } else {
        vec![
            serde_json::json!("Inspect the existing plugin project conventions before editing."),
            serde_json::json!("Respect message/stage/filtering attributes from writeTarget."),
            serde_json::json!("Do not register plugins from MCP."),
        ]
    };

    // ── Forbidden assumptions + forbiddenAssumptions ──────────────────────────
    let forbidden_assumptions: Vec<String> = plan["unmappedSourceFields"].as_array()
        .map(|fields| fields.iter()
            .filter_map(|f| f.as_str().or_else(|| f["source"].as_str()))
            .map(|f| format!("Do not map {} unless a target field is explicitly present in fieldMappings.", f))
            .collect())
        .unwrap_or_default();

    // ── validationFields: from template additionalSourceFields, referenced/affected fields
    // (ui-business-rule/ribbon-action scripts), or text extraction ──
    let validation_fields: Vec<Value> = {
        let mut vf: Vec<Value> = Vec::new();
        if let Some(tpl) = &template {
            if let Some(add) = tpl["additionalSourceFields"].as_array() {
                let src_entity = tpl["sourceEntity"].as_str().unwrap_or("source");
                for f in add {
                    if let Some(fname) = f.as_str() {
                        vf.push(serde_json::json!(format!("{}.{}", src_entity, fname)));
                    }
                }
            }
        }
        if is_non_mapping_pattern {
            if let Some(entity) = target_entity {
                let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
                for f in referenced_fields.iter().chain(affected_fields.iter()) {
                    if let Some(fname) = f.as_str() {
                        if seen.insert(fname.to_string()) {
                            vf.push(serde_json::json!(format!("{}.{}", entity, fname)));
                        }
                    }
                }
            }
        }
        vf.extend(text_extracted_validation.iter().cloned());
        vf
    };

    // ── missingRequiredMappings ───────────────────────────────────────────────
    let missing_required_mappings: Vec<Value> = if field_mappings_missing {
        if template_needs_mapping {
            if let Some(tpl) = &template {
                let source_entity = tpl["sourceEntity"].as_str().unwrap_or("source");
                let target_ent = target_entity.unwrap_or("");
                let src_fields: Vec<&str> = tpl["sourceFields"]
                    .as_array()
                    .map(|a| a.iter().filter_map(|v| v.as_str()).collect())
                    .unwrap_or_default();
                let tgt_fields: Vec<&str> = tpl["targetFields"]
                    .as_array()
                    .map(|a| a.iter().filter_map(|v| v.as_str()).collect())
                    .unwrap_or_default();
                let pair_count = src_fields.len().min(tgt_fields.len());
                (0..pair_count)
                    .map(|i| {
                        serde_json::json!(format!(
                            "{}.{} -> {}.{}",
                            source_entity, src_fields[i], target_ent, tgt_fields[i]
                        ))
                    })
                    .collect()
            } else {
                vec![]
            }
        } else if text_detected_required {
            vec![serde_json::json!("Field mapping work detected in original assignment but target field assignments could not be safely extracted. Define field mappings in the technical plan using prepare_developer_task.")]
        } else {
            plan["unmappedSourceFields"]
                .as_array()
                .cloned()
                .unwrap_or_default()
                .iter()
                .filter_map(|f| f.as_str())
                .map(|f| serde_json::json!(format!("{} (no target field defined in plan)", f)))
                .collect()
        }
    } else {
        vec![]
    };

    let scaffold_only = field_mappings_missing
        || (requires_field_mappings && final_field_mappings.is_empty())
        || scaffold_signal_detected
        || final_consistency_guard_applied;

    // ── AI Kit ────────────────────────────────────────────────────────────────
    let ai_kit_available = ai_kit_path.is_some();
    let ai_kit_rules_files: Vec<String> = if let Some(kit) = ai_kit_path.filter(|s| !s.is_empty()) {
        let rules_rel = if work_kind == "plugin" {
            "ai-rules/crm-plugin-rules.md"
        } else if work_kind == "ribbon" {
            "ai-rules/crm-ribbon-rules.md"
        } else {
            "ai-rules/crm-javascript-rules.md"
        };
        let sep = if kit.ends_with('/') || kit.ends_with('\\') {
            ""
        } else {
            "/"
        };
        vec![format!("{kit}{sep}{rules_rel}")]
    } else {
        vec![]
    };
    let ai_kit_review_note = if is_script {
        "Run AI Kit review for the created/updated script before upload or registration."
    } else {
        "Run AI Kit review for the created/updated plugin before registration."
    };

    let recommended_next_action = if can_write {
        "Implement only the work described in this packet.".to_string()
    } else {
        blocking_user_action
            .as_str()
            .or_else(|| readiness["recommendedNextStep"].as_str())
            .unwrap_or("Resolve Task Workbench blockers before implementation.")
            .to_string()
    };

    let field_mappings_source = if !text_extracted_mappings.is_empty() {
        "text-extracted"
    } else if !template_field_mappings.is_empty() {
        "template"
    } else if !plan_field_mappings.is_empty() {
        "plan"
    } else {
        "none"
    };

    let mut packet = serde_json::json!({
        "taskId": task["id"].as_str().unwrap_or(""),
        "packetGeneratorVersion": DEVELOPER_WORK_PACKET_VERSION,
        "status": if can_write { "ready_to_code" } else { "not_ready" },
        "canWriteCode": can_write,
        "decisionReason": decision_reason,
        "blockingUserAction": blocking_user_action,
        "blockers": blockers,
        "warnings": readiness["warnings"].as_array().cloned().unwrap_or_default(),
        "recommendedNextAction": recommended_next_action,
        "writeTarget": write_target,
        "implementation": {
            "workKind": work_kind,
            "implementationPattern": implementation_pattern,
            "summary": task_mcp_summarize(plan["summary"].as_str()
                .or_else(|| task["analysisResult"]["summaryEn"].as_str())
                .or_else(|| task["analysisResult"]["summary"].as_str())
                .or_else(|| task["title"].as_str()), TASK_MCP_MAX_SUMMARY_LENGTH),
            "steps": sanitized_steps,
            "requiresFieldMappings": requires_field_mappings,
            "fieldMappings": final_field_mappings,
            "fieldMappingsCount": final_field_mappings.len(),
            "fieldMappingsSource": field_mappings_source,
            "unmappedSourceFields": plan["unmappedSourceFields"].as_array().cloned().unwrap_or_default(),
            // UI/business-rule and ribbon-action script context — workflowSetup first, then
            // template. Not used for field-mapping scripts, which use fieldMappings above instead.
            "referencedFields": referenced_fields,
            "triggerFields": trigger_fields,
            "affectedFields": affected_fields,
            "uiRules": ui_rules,
            "optionSetValues": option_set_values,
            "notificationIds": notification_ids,
            "forbiddenOperations": forbidden_operations,
            "validationFields": validation_fields,
            "missingRequiredMappings": missing_required_mappings,
            "scaffoldOnly": scaffold_only,
            "scaffoldSignalDetected": scaffold_signal_detected,
            "scaffoldSignalSources": scaffold_signal_sources,
            "finalConsistencyGuardApplied": final_consistency_guard_applied,
            "detectionSources": text_detection_sources,
            "forbiddenAssumptions": forbidden_assumptions,
            "risks": sanitized_risks,
            "businessRules": template.as_ref().and_then(|t| t["businessRules"].as_array()).cloned().unwrap_or_default(),
            "acceptanceCriteria": template.as_ref().and_then(|t| t["acceptanceCriteria"].as_array()).cloned().unwrap_or_default(),
        },
        "conventions": {
            "sources": convention_sources,
            "relatedFiles": setup["relatedExistingFiles"].as_array().cloned().unwrap_or_default(),
            "rules": convention_rules,
        },
        "dataverse": {
            "verificationStatus": verification["verdict"].as_str().unwrap_or("unknown"),
            "report": verification,
            "instruction": if is_script {
                "Dataverse Metadata Check for script/ribbon files runs automatically via run_implementation_verification (Primarch, when configured) after implementation. Use the stored report here if already present."
            } else {
                "Use the stored Dataverse verification report. If missing or failing, resolve before implementation."
            },
        },
        "aiKit": {
            "available": ai_kit_available,
            "mustInspectBeforeWriting": true,
            "rulesFiles": ai_kit_rules_files,
            "mandatoryRulesSummary": [
                "No TODO comments, placeholder methods, or stub implementations in production code.",
                "Do not create placeholder or stub handlers.",
                "Do not add early returns unless existing scripts in the repository use them.",
                "Implement only exact fields and entities from the work packet.",
                "Do not invent fields, mappings, or web resource names.",
            ],
            "reviewRequiredAfterImplementation": true,
            "reviewNote": ai_kit_review_note,
        },
        "reviewTestCommit": {
            "beforeCoding": [
                "Use this work packet as the source of truth.",
                "Do not call low-level setup tools unless this packet explicitly says setup is incomplete."
            ],
            "localValidation": plan["testChecklist"].as_array().cloned().unwrap_or_default(),
            "afterImplementation": [
                "After writing implementation files: re-read the file and verify every businessRule and acceptanceCriteria in the packet is satisfied.",
                "Call record_ai_implementation_completed with taskId, filesChanged, and a short summary. This records the implementation and advances the workflow.",
                "Call continue_developer_workflow after record_ai_implementation_completed. If it returns nextAction=run_implementation_verification, call run_implementation_verification.",
                "If run_implementation_verification returns fixableFindings, fix the code and repeat: record_ai_implementation_completed, continue_developer_workflow, run_implementation_verification.",
                "Stop only when continue_developer_workflow returns wait_for_user — report the required manual action and wait.",
                "Do not call record_local_test for script tasks — use record_ai_implementation_completed instead.",
                "Do not perform Dataverse upload, plugin registration, GitHub/ADO writes, or deployment without explicit approval."
            ],
            "commit": [
                "Use Task Workbench git tools only after implementation and validation are complete.",
                "Commit only files related to this task.",
                "Push only through the guarded task branch flow; no force push and no direct main/master push."
            ],
        },
        "internalStateSummary": {
            "currentStep": workflow["currentStep"].as_str(),
            "planApproved": approval["approved"].as_bool().unwrap_or(false),
            "nextRecommendedStep": next["step"].as_str(),
        },
        "task": task_mcp_safe_task_summary(task),
    });
    // Post-packet filter: remove risks that mention CRM entity names absent from the trusted packet.
    // Applied after full assembly so writeTarget (targetEntity, eventFieldName) is available.
    // Only runs when the packet is ready-to-code with concrete field mappings — the same condition
    // used by sanitized_risks — to avoid silently dropping risks on unapproved/incomplete plans.
    if can_write && !final_field_mappings.is_empty() {
        let allowed = task_mcp_build_allowed_logical_names(&packet);
        if let Some(risks) = packet["implementation"]["risks"].as_array().cloned() {
            let filtered: Vec<Value> = risks
                .into_iter()
                .filter(|v| {
                    let t = v
                        .as_str()
                        .map(str::to_string)
                        .unwrap_or_else(|| v.to_string());
                    !task_mcp_risk_mentions_unknown_entity(&t, &allowed)
                })
                .collect();
            packet["implementation"]["risks"] = Value::Array(filtered);
        }
    }
    packet
}

