/// Generates a UUID v4 string using the existing `rand` crate (no extra dependencies).
fn task_mcp_generate_id() -> String {
    use rand::Rng;
    let bytes: [u8; 16] = rand::thread_rng().gen();
    let b6 = (bytes[6] & 0x0f) | 0x40; // version 4
    let b8 = (bytes[8] & 0x3f) | 0x80; // variant 10xx
    format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        bytes[0], bytes[1], bytes[2], bytes[3],
        bytes[4], bytes[5],
        b6, bytes[7],
        b8, bytes[9],
        bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15],
    )
}

/// Maps task status + waitingState to the human-readable display phase.
fn task_mcp_display_phase(task: &Value) -> &'static str {
    if task["waitingState"].as_str() == Some("consultant-testing") {
        return "testing";
    }
    match task["status"].as_str().unwrap_or("new") {
        "in-progress" => "development",
        "ready-for-review" => "review",
        "new" => "new",
        "analyzed" => "analyzed",
        "done" => "done",
        "blocked" => "blocked",
        _ => "new",
    }
}

/// Sanitizes a JSON array of strings into a Vec<Value>, applying length/count limits.
fn task_mcp_collect_string_array(value: &Value, max_count: usize, max_len: usize) -> Vec<Value> {
    let Some(arr) = value.as_array() else {
        return vec![];
    };
    arr.iter()
        .take(max_count)
        .filter_map(|v| v.as_str())
        .map(|s| task_mcp_normalize_small_text(s, max_len))
        .filter(|s| !s.is_empty())
        .map(Value::String)
        .collect()
}

/// Returns the MCP override status for a checklist key, or None if not overridden.
fn task_mcp_checklist_override(task: &Value, key: &str) -> Option<String> {
    task.get("mcpChecklistOverrides")
        .and_then(|v| v.get(key))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

/// Builds a checklist JSON array mirroring TypeScript buildWorkflowChecklist.
fn task_mcp_workflow_checklist(task: &Value) -> Vec<Value> {
    let wf = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let ver = task
        .get("crmVerificationReports")
        .and_then(|v| v.as_array())
        .and_then(|arr| arr.first());
    let ver_verdict = ver.and_then(|v| v["verdict"].as_str()).unwrap_or("none");
    let ver_ok = matches!(ver_verdict, "pass" | "warnings");
    let ver_fail = ver_verdict == "fail";

    let plan_approved = wf["planApproval"]["approved"].as_bool().unwrap_or(false)
        && wf["planApproval"]["invalidatedAt"].is_null();
    let diff_approved = wf["diffApproval"]["approved"].as_bool().unwrap_or(false)
        && wf["diffApproval"]["invalidatedAt"].is_null();
    let consultant_done = (wf["externalExecution"]["completed"]
        .as_bool()
        .unwrap_or(false)
        && wf["externalExecution"]["invalidatedAt"].is_null())
        || task
            .get("consultantTestRecord")
            .and_then(|v| v["status"].as_str())
            == Some("confirmed");
    let pr_tracked = wf["pullRequestTracking"]["createdManually"]
        .as_bool()
        .unwrap_or(false)
        && wf["pullRequestTracking"]["invalidatedAt"].is_null();
    let review_done =
        !wf["pullRequestReview"].is_null() && wf["pullRequestReview"]["invalidatedAt"].is_null();
    let review_needs_attention = wf["pullRequestReview"]["attentionRequired"]
        .as_bool()
        .unwrap_or(false);

    let status = task["status"].as_str().unwrap_or("new");
    let waiting = task["waitingState"].as_str().unwrap_or("");
    let is_in_progress = status == "in-progress";
    let is_testing = waiting == "consultant-testing";
    let is_review = status == "ready-for-review";
    let is_done = status == "done";
    let has_analysis = !task["analysisResult"].is_null() || status != "new";
    let setup_confirmed = task
        .get("workflowSetup")
        .map_or(false, |ws| !ws["confirmedAt"].is_null());

    let local_test_status = task
        .get("localTestRecord")
        .and_then(|v| v["status"].as_str())
        .unwrap_or("");
    let consultant_not_needed = task
        .get("consultantTestRecord")
        .and_then(|v| v["status"].as_str())
        == Some("not-needed");

    // Helper: override if set, else return default
    macro_rules! ov {
        ($key:expr, $default:expr) => {
            task_mcp_checklist_override(task, $key).unwrap_or_else(|| $default.to_string())
        };
    }

    let analyzed = ov!(
        "task-analyzed",
        if has_analysis { "done" } else { "pending" }
    );
    let setup = ov!(
        "setup-confirmed",
        if setup_confirmed { "done" } else { "pending" }
    );
    let crm_ver = ov!(
        "crm-metadata-verified",
        if ver_fail {
            "warning"
        } else if ver_ok {
            "done"
        } else {
            "pending"
        }
    );
    let tech_plan = ov!(
        "technical-plan-ready",
        if plan_approved {
            "done"
        } else if !wf["technicalPlan"].is_null() {
            "partial"
        } else {
            "pending"
        }
    );
    let impl_done = ov!(
        "implementation-done",
        if diff_approved {
            "done"
        } else if is_in_progress && !is_testing {
            "active"
        } else {
            "pending"
        }
    );
    let local_test = ov!(
        "local-test-done",
        match local_test_status {
            "passed" => "done",
            "failed" => "warning",
            "not-needed" => "optional",
            _ => "pending",
        }
    );
    let consultant = ov!(
        "consultant-testing",
        if consultant_done {
            "done"
        } else if is_testing {
            "active"
        } else if consultant_not_needed {
            "optional"
        } else {
            "skip"
        }
    );
    let pr = ov!(
        "pull-request",
        if pr_tracked {
            "done"
        } else if is_review {
            "active"
        } else {
            "pending"
        }
    );
    let review = ov!(
        "code-review",
        if review_done {
            if review_needs_attention {
                "warning"
            } else {
                "done"
            }
        } else {
            "pending"
        }
    );
    let done = ov!("done", if is_done { "done" } else { "pending" });

    vec![
        serde_json::json!({"key":"task-analyzed",        "label":"Task analyzed",       "status": analyzed}),
        serde_json::json!({"key":"setup-confirmed",      "label":"Setup confirmed",     "status": setup}),
        serde_json::json!({"key":"crm-metadata-verified","label":"CRM metadata verified","status": crm_ver}),
        serde_json::json!({"key":"technical-plan-ready", "label":"Technical plan ready","status": tech_plan}),
        serde_json::json!({"key":"implementation-done",  "label":"Implementation done", "status": impl_done}),
        serde_json::json!({"key":"local-test-done",      "label":"Local test",          "status": local_test}),
        serde_json::json!({"key":"consultant-testing",   "label":"Consultant testing",  "status": consultant}),
        serde_json::json!({"key":"pull-request",         "label":"Pull request",        "status": pr}),
        serde_json::json!({"key":"code-review",          "label":"Code review",         "status": review}),
        serde_json::json!({"key":"done",                 "label":"Done",                "status": done}),
    ]
}

fn task_mcp_normalize_small_text(input: &str, max_len: usize) -> String {
    task_mcp_strip_html(input)
        .chars()
        .take(max_len)
        .collect::<String>()
        .trim()
        .to_string()
}

fn task_mcp_append_audit_note(task: &mut Value, action: &str) {
    let when = chrono_now_iso();
    let line = format!("[{when}] MCP local write: {action}");
    let existing = task["notes"].as_str().unwrap_or("").trim();
    let next = if existing.is_empty() {
        line
    } else {
        format!("{existing}\n{line}")
    };
    task["notes"] = Value::String(next);
}

fn task_mcp_find_task_index(tasks: &[Value], task_id: &str) -> Option<usize> {
    tasks
        .iter()
        .position(|task| task["id"].as_str().unwrap_or("") == task_id)
}

fn task_mcp_load_tasks(app: &tauri::AppHandle) -> Result<Vec<Value>, String> {
    let dir = app_data_dir(app)?;
    let repo = SqliteWorkItemRepository::in_app_data(&dir);
    repo.migrate_json_tasks(&dir.join("tasks.json")).map_err(|e| e.message)?;
    repo.list_legacy_compatible().map_err(|e| e.message)
}

fn task_mcp_save_tasks(app: &tauri::AppHandle, tasks: &[Value]) -> Result<(), String> {
    let dir = app_data_dir(app)?;
    let repo = SqliteWorkItemRepository::in_app_data(&dir);
    repo.sync_legacy_snapshot(tasks).map_err(|e| e.message)
}

fn task_mcp_get_task<'a>(tasks: &'a [Value], task_id: &str) -> Option<&'a Value> {
    tasks
        .iter()
        .find(|task| task["id"].as_str().unwrap_or("") == task_id)
}

fn task_mcp_next_recommended_step(task: &Value) -> Value {
    if !task_mcp_is_developer_task(task) {
        return serde_json::json!({
            "step": "none",
            "attentionRequired": false,
            "reason": "This does not appear to be a CRM developer workflow task.",
        });
    }

    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    if !workflow.is_object() {
        return serde_json::json!({
            "step": "diagnosis",
            "attentionRequired": true,
            "reason": "Open the task in task-workbench and save the local CRM workflow diagnosis state.",
        });
    }

    if workflow["technicalPlan"].is_null() {
        return serde_json::json!({
            "step": "technical-plan",
            "attentionRequired": true,
            "reason": "Generate a deterministic local technical implementation plan.",
        });
    }

    let plan_approved = workflow["planApproval"]["approved"]
        .as_bool()
        .unwrap_or(false)
        && workflow["planApproval"]["invalidatedAt"].is_null();
    if !plan_approved {
        return serde_json::json!({
            "step": "technical-plan",
            "attentionRequired": true,
            "reason": "Review and approve the technical implementation plan.",
        });
    }

    // Plan is approved — delegate to the same post-implementation computation used by
    // continue_developer_workflow, so the UI-visible next step always matches the AI-facing one.
    let continue_step = task_mcp_compute_continue_workflow_step(task);
    serde_json::json!({
        "step": continue_step["nextAction"].as_str().unwrap_or("diagnosis"),
        "attentionRequired": continue_step["requiresUserApproval"].as_bool().unwrap_or(true),
        "reason": continue_step["blockingUserAction"].as_str()
            .or_else(|| continue_step["instructionForAI"].as_str())
            .unwrap_or("Continue the current local CRM workflow step.")
            .to_string(),
    })
}

/// Sets the canonical UI-visible status/waitingState/attentionState fields for a workflow phase.
/// This is the single place that maps a phase name to the fields TaskDetail / workflowPlan.ts /
/// CrmDeveloperWorkflowPanel read to render the top-level workflow phase (NEW/ANALYZED/
/// DEVELOPMENT/TESTING/CODE REVIEW/DONE). Used by both the `set_task_phase` tool and
/// `task_mcp_apply_developer_workflow_transition` so UI actions and MCP writes never diverge.
fn task_mcp_set_status_phase(task: &mut Value, phase: &str) {
    match phase {
        "new" => {
            task["status"] = serde_json::json!("new");
            task["waitingState"] = Value::Null;
            task["attentionState"] = Value::Null;
        }
        "analyzed" => {
            task["status"] = serde_json::json!("analyzed");
            task["waitingState"] = Value::Null;
            task["attentionState"] = Value::Null;
        }
        "development" => {
            task["status"] = serde_json::json!("in-progress");
            task["waitingState"] = Value::Null;
            task["attentionState"] = Value::Null;
        }
        "testing" => {
            task["status"] = serde_json::json!("in-progress");
            task["waitingState"] = serde_json::json!("consultant-testing");
            task["attentionState"] = Value::Null;
        }
        "review" => {
            task["status"] = serde_json::json!("ready-for-review");
            task["waitingState"] = serde_json::json!("code-review");
            task["attentionState"] = Value::Null;
        }
        "done" => {
            task["status"] = serde_json::json!("done");
            task["waitingState"] = Value::Null;
            task["attentionState"] = Value::Null;
            task["completedAt"] = serde_json::json!(chrono_now_iso());
        }
        _ => {}
    }
}

/// Task fields representing generated analysis, setup confirmation, approvals, implementation,
/// verification, testing, PR/review, external-action, or workflow-progression state. Cleared by a
/// full reset to NEW (see task_mcp_reset_task_workflow_to_new below). Deliberately excludes
/// status/waitingState/attentionState/suggestedActions — those are unconditionally reset to their
/// NEW-equivalent value regardless of whether any of the keys below are set.
/// Mirrors RESETTABLE_WORKFLOW_KEYS in src/lib/taskWorkflowReset.ts and mcp/task-workbench-mcp.mjs
/// — keep all three in sync.
const TASK_MCP_RESETTABLE_WORKFLOW_KEYS: &[&str] = &[
    "completedAt",
    "estimatedEffort",
    "planningBucket",
    "suggestedPlanningBucket",
    "priorityScore",
    "priorityReason",
    "isPlanningLocked",
    "analysisResult",
    "generatedReply",
    "scriptAnalysis",
    "selectedPluginProject",
    "aiFileReviews",
    "crmSkeletons",
    "crmVerificationReports",
    "crmDeveloperWorkflow",
    "workflowSetup",
    "taskMode",
    "implementationVerification",
    "deploymentTesting",
    "localTestRecord",
    "consultantTestRecord",
    "mcpChecklistOverrides",
    "mcpNextStep",
    "gitWorkflow",
];

/// True for any value that represents real, meaningful workflow state worth warning about —
/// false for null and for empty arrays/objects (nothing was actually recorded there).
fn task_mcp_is_non_empty_workflow_value(value: &Value) -> bool {
    match value {
        Value::Null => false,
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
        _ => true,
    }
}

/// True when the task carries any generated/derived workflow state that a reset to NEW would
/// discard. Used to decide whether resetting requires explicit confirmation (set_task_phase's
/// confirmReset) — a task with none of this state is already effectively clean, and resetting it
/// is a safe no-op. Mirrors JS taskHasResettableWorkflowState.
fn task_mcp_task_has_resettable_workflow_state(task: &Value) -> bool {
    TASK_MCP_RESETTABLE_WORKFLOW_KEYS
        .iter()
        .any(|key| task_mcp_is_non_empty_workflow_value(&task[key]))
}

/// Resets a task's local workflow/execution state to the equivalent of a fresh NEW task, in
/// place. Preserves identity, original assignment, user notes, and import/tracking metadata —
/// only status/waitingState/attentionState/suggestedActions and the
/// TASK_MCP_RESETTABLE_WORKFLOW_KEYS fields are touched. Removes (rather than nulling) the
/// resettable keys so no stale nested object/array lingers in the persisted JSON. Never touches
/// the filesystem, Git, Dataverse, or any external system — this is a pure in-memory mutation.
/// Decides whether set_task_phase's phase="new" reset may proceed: rejects with the confirmation-
/// required message when the task carries resettable state and confirmReset was not explicitly
/// set, otherwise allows it (idempotent no-op case and explicit-confirmation case both return Ok).
/// Pure — no I/O — so the confirmReset gate is unit-testable without a full task_mcp_execute_tool
/// dispatch. The "set_task_phase" match arm calls this before task_mcp_reset_task_workflow_to_new.
fn task_mcp_decide_new_phase_reset(
    task: &Value,
    confirm_reset: bool,
    task_id: &str,
) -> Result<(), String> {
    if task_mcp_task_has_resettable_workflow_state(task) && !confirm_reset {
        return Err(format!(
            "Resetting task '{task_id}' to NEW will clear saved analysis, developer setup, technical plans and \
            approvals, implementation verification, AI reviews, test/checklist results, next-step state, and local \
            Git workflow tracking. The original assignment, customer, notes, tracking links, and repository files \
            will not be changed — this does not touch Git or any external system. Explicit user approval is \
            required before this reset can proceed. Ask the user to confirm, then retry with confirmReset=true."
        ));
    }
    Ok(())
}

/// Mirrors JS resetTaskWorkflowToNew.
fn task_mcp_reset_task_workflow_to_new(task: &mut Value) {
    task["status"] = serde_json::json!("new");
    task["waitingState"] = Value::Null;
    task["attentionState"] = Value::Null;
    task["suggestedActions"] = serde_json::json!([]);
    if let Some(obj) = task.as_object_mut() {
        for key in TASK_MCP_RESETTABLE_WORKFLOW_KEYS {
            obj.remove(*key);
        }
    }
}

/// Canonical developer workflow transition service. Both MCP write tools and (in future) UI
/// actions must call this instead of writing `status`/`waitingState`/helper fields ad hoc, so
/// the app-visible phase never drifts from what MCP tools recorded.
///
/// `payload` carries transition-specific inputs as a JSON object (e.g. `{"canWriteCode": true}`
/// for `technical_plan_approved`). Unknown transitions are a no-op.
fn task_mcp_apply_developer_workflow_transition(
    task: &mut Value,
    transition: &str,
    payload: &Value,
) {
    match transition {
        "technical_plan_approved" => {
            // Leaving NEW/Analyze: a plan can only be approved once the task has been analyzed.
            if task["status"].as_str() == Some("new") {
                task_mcp_set_status_phase(task, "analyzed");
            }
            // If code can now be written (all other gates satisfied), move straight into
            // DEVELOPMENT so the UI does not show a stale NEW/Analyze or Analyzed phase.
            let can_write_code = payload["canWriteCode"].as_bool().unwrap_or(false);
            if can_write_code && task["status"].as_str() != Some("in-progress") {
                task_mcp_set_status_phase(task, "development");
            }
        }
        "ai_implementation_completed" => {
            // Implementation files were written by AI. This is DEVELOPMENT / Verify
            // Implementation — do not set a testing waitingState here; the manual CRM
            // upload + in-app Verify Implementation step still has to happen first.
            if task["status"].as_str() != Some("in-progress") {
                task_mcp_set_status_phase(task, "development");
            }
        }
        "manual_crm_verification_completed" => {
            // Manual CRM upload/registration + Verify Implementation is done — hand off to
            // consultant testing.
            task_mcp_set_status_phase(task, "testing");
        }
        _ => {}
    }
    if task["crmDeveloperWorkflow"].is_null() {
        task["crmDeveloperWorkflow"] = serde_json::json!({});
    }
    task["crmDeveloperWorkflow"]["updatedAt"] = serde_json::json!(chrono_now_iso());
}

/// Builds the same simplified workflow state returned by `get_task_workflow_overview`, for
/// embedding into write-tool responses so callers can verify the UI-visible phase moved
/// without a second round-trip.
fn task_mcp_workflow_overview(task: &Value) -> Value {
    // Modal-truth Verify Implementation summary — the same shape run_implementation_verification
    // and get_implementation_verification_summary return, so MCP callers never have to guess
    // modal-visible statuses from a separate call, and never have to re-derive unresolved rows
    // from prose.
    let implementation_verification = task_mcp_build_modal_verification_summary(task);
    let unresolved_required_rows = task_mcp_unresolved_modal_rows(&implementation_verification);

    serde_json::json!({
        "displayPhase":          task_mcp_display_phase(task),
        "status":                task["status"].as_str(),
        "waitingState":          task["waitingState"].as_str(),
        "attentionState":        task["attentionState"].as_str(),
        "checklist":             task_mcp_workflow_checklist(task),
        // task.localTestRecord is the continue_developer_workflow step-1 gate / AI implementation-
        // completion helper — NOT the modal's Local Test row (implementationVerification.localTest).
        // Exposed separately and clearly labeled so it can never be read as verification truth.
        "legacyLocalTestRecord": {
            "status": task["localTestRecord"]["status"].as_str(),
            "ignoredForImplementationVerification": true,
        },
        "consultantTestRecord":  task.get("consultantTestRecord").cloned().unwrap_or(Value::Null),
        "mcpNextStep":           task.get("mcpNextStep").cloned().unwrap_or(Value::Null),
        "implementationVerification": implementation_verification,
        "unresolvedRequiredRows": unresolved_required_rows,
        "nextRecommendedStep":   task_mcp_next_recommended_step(task),
    })
}

/// True for script/ribbon (JS/TS form) developer tasks. Mirrors the JS `isScriptWorkflowTask`
/// helper in mcp/task-workbench-mcp.mjs — keep both in sync.
fn task_mcp_is_script_workflow_task(task: &Value) -> bool {
    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let work_kind = workflow["detectedWorkKind"]
        .as_str()
        .or_else(|| setup["devTargetKind"].as_str())
        .unwrap_or("unknown");
    work_kind == "script"
        || work_kind == "ribbon"
        || setup["devTargetKind"].as_str() == Some("script")
}

/// Picks the file from filesChanged that best matches the task's known script artifact/name.
/// Mirrors the JS `resolveImplementedScriptArtifact` helper.
fn task_mcp_resolve_implemented_script_artifact(
    task: &Value,
    files_changed: &[&str],
) -> Option<String> {
    let normalize = |p: &str| p.replace('\\', "/").to_lowercase();
    let script_candidates: Vec<&str> = files_changed
        .iter()
        .copied()
        .filter(|f| {
            let lower = f.to_lowercase();
            lower.ends_with(".js")
                || lower.ends_with(".ts")
                || lower.ends_with(".jsx")
                || lower.ends_with(".tsx")
        })
        .collect();
    if script_candidates.is_empty() {
        return None;
    }

    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    let desired = setup["desiredScriptFile"]
        .as_str()
        .map(normalize)
        .filter(|s| !s.is_empty());
    let existing = setup["artifactPath"]
        .as_str()
        .or_else(|| setup["scriptPath"].as_str())
        .map(normalize)
        .filter(|s| !s.is_empty());

    if let Some(desired) = &desired {
        if let Some(m) = script_candidates
            .iter()
            .find(|f| normalize(f).ends_with(desired.as_str()))
        {
            return Some((*m).to_string());
        }
    }
    if let Some(existing) = &existing {
        if let Some(m) = script_candidates.iter().find(|f| {
            let nf = normalize(f);
            nf == *existing || existing.ends_with(nf.as_str())
        }) {
            return Some((*m).to_string());
        }
    }
    Some(script_candidates[0].to_string())
}

/// Persists the file AI just implemented into the UI-visible script selection fields, so
/// TaskDevModePanel / ImplementationVerificationModal / repositoryContext.ts resolve to the
/// actual implemented artifact instead of a stale or empty workflowSetup.artifactPath.
fn task_mcp_apply_implemented_script_artifact(task: &mut Value, implemented_path: &str) {
    if task["workflowSetup"].is_null() {
        task["workflowSetup"] = serde_json::json!({});
    }
    let normalized = implemented_path.replace('\\', "/");
    let file_name = normalized
        .rsplit('/')
        .next()
        .unwrap_or(&normalized)
        .to_string();
    task["workflowSetup"]["artifactPath"] = serde_json::json!(implemented_path);
    task["workflowSetup"]["desiredScriptFile"] = serde_json::json!(file_name);
    let is_absolute = std::path::Path::new(implemented_path).is_absolute();
    if is_absolute {
        task["workflowSetup"]["absoluteScriptPath"] = serde_json::json!(implemented_path);
    } else if let Some(repo_root) = task["workflowSetup"]["repositoryRoot"]
        .as_str()
        .filter(|s| !s.is_empty())
    {
        let joined = std::path::Path::new(repo_root).join(implemented_path);
        task["workflowSetup"]["absoluteScriptPath"] =
            serde_json::json!(joined.to_string_lossy().to_string());
    }
}

/// Resolves an absolute filesystem path for the task's current script artifact, if known.
fn task_mcp_resolve_script_absolute_path(task: &Value) -> Option<String> {
    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    if let Some(p) = setup["absoluteScriptPath"]
        .as_str()
        .filter(|s| !s.is_empty())
    {
        return Some(p.to_string());
    }
    let artifact = setup["artifactPath"]
        .as_str()
        .or_else(|| setup["scriptPath"].as_str())?;
    if artifact.is_empty() {
        return None;
    }
    if std::path::Path::new(artifact).is_absolute() {
        return Some(artifact.to_string());
    }
    let repo_root = setup["repositoryRoot"].as_str().filter(|s| !s.is_empty())?;
    Some(
        std::path::Path::new(repo_root)
            .join(artifact)
            .to_string_lossy()
            .to_string(),
    )
}

/// Deterministic regex-free business-rule check for one static rule id. Keep in sync with the
/// `pattern`/`type` entries of the matching template's staticRules in mcp/task-workbench-mcp.mjs
/// and task_mcp_builtin_templates() below — Rust has no regex dependency, so rules are
/// hand-implemented substring/proximity checks instead of compiled patterns.
fn task_mcp_static_rule_matches(rule_id: &str, content: &str, content_lower: &str) -> bool {
    match rule_id {
        "retrieve-source-entity" => {
            content_lower.contains("retrieverecord") && content_lower.contains("nvr_customerasset")
        }
        "no-xrm-page" => content.contains("Xrm.Page"),
        "no-autosave" => content_lower.contains(".data.save("),
        "no-webresource-upload" => {
            content_lower.contains("uploadwebresource")
                || content_lower.contains("registerevent")
                || content_lower.contains("updatewebresourceset")
        }
        "no-todo-fixme-placeholder" => {
            content_lower.contains("todo")
                || content_lower.contains("fixme")
                || content_lower.contains("placeholder")
        }
        "no-empty-lookup-entitytype" => [
            "entitytype: \"\"",
            "entitytype:\"\"",
            "entitytype: ''",
            "entitytype:''",
        ]
        .iter()
        .any(|p| content_lower.contains(p)),
        "no-write-validationfields" => {
            task_mcp_call_contains_arg(content_lower, "setvalue(", "nvr_statuscustom")
        }
        "status-custom-checks-inactive-values" => {
            content_lower.contains("inactive")
                || content_lower.contains("retired")
                || content_lower.contains("lost")
        }
        "notification-on-inactive-status" => content_lower.contains("notification"),
        _ => false,
    }
}

/// Scans for `call_prefix` occurrences and checks whether `arg` appears before the call's
/// closing parenthesis (a lightweight stand-in for `setValue\(([^)]*arg)\)`-style regex).
fn task_mcp_call_contains_arg(content_lower: &str, call_prefix: &str, arg: &str) -> bool {
    let mut search_from = 0usize;
    while let Some(idx) = content_lower[search_from..].find(call_prefix) {
        let start = search_from + idx + call_prefix.len();
        if start >= content_lower.len() {
            break;
        }
        if let Some(end_rel) = content_lower[start..].find(')') {
            if content_lower[start..start + end_rel].contains(arg) {
                return true;
            }
        }
        search_from = start;
    }
    false
}

/// Runs the matched template's staticRules against implemented file content. No LLM call.
/// Returns (status, findings, fixable_findings).
fn task_mcp_run_static_business_rule_checks(
    template: Option<&Value>,
    file_content: &str,
) -> (String, Vec<String>, Vec<Value>) {
    let rules = template
        .and_then(|t| t["staticRules"].as_array())
        .cloned()
        .unwrap_or_default();
    if rules.is_empty() {
        return (
            "skipped".to_string(),
            vec!["No static rules are defined for this task template.".to_string()],
            vec![],
        );
    }
    let content_lower = file_content.to_lowercase();
    let mut findings = Vec::new();
    let mut fixable = Vec::new();
    for rule in &rules {
        let id = rule["id"].as_str().unwrap_or("").to_string();
        let description = rule["description"].as_str().unwrap_or("").to_string();
        let rule_type = rule["type"].as_str().unwrap_or("must-match");
        let matched = task_mcp_static_rule_matches(&id, file_content, &content_lower);
        let pass = if rule_type == "must-not-match" {
            !matched
        } else {
            matched
        };
        findings.push(format!(
            "{}|{}",
            if pass { "pass" } else { "fail" },
            description
        ));
        if !pass {
            fixable.push(serde_json::json!({ "id": id, "description": description }));
        }
    }
    let status = if fixable.is_empty() {
        "passed"
    } else {
        "failed"
    };
    (status.to_string(), findings, fixable)
}

/// Statuses that count as "resolved" for a modal check row without MCP re-running it.
fn task_mcp_impl_check_resolved(status: &str) -> bool {
    matches!(
        status,
        "passed" | "warnings" | "skipped" | "manually-verified" | "failed"
    )
}

/// True for script/ribbon AND plugin tasks — the task kinds run_implementation_verification's
/// hard-gate pipeline covers. Other kinds (repo-only, bugfix, review, general) are not part of
/// the orchestrated verification pipeline and keep using their existing manual workflow.
fn task_mcp_is_verifiable_dev_task(task: &Value) -> bool {
    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let work_kind = workflow["detectedWorkKind"]
        .as_str()
        .or_else(|| setup["devTargetKind"].as_str())
        .unwrap_or("unknown");
    matches!(work_kind, "script" | "ribbon" | "plugin")
        || matches!(
            setup["devTargetKind"].as_str(),
            Some("script") | Some("plugin")
        )
}

fn task_mcp_is_plugin_dev_task(task: &Value) -> bool {
    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    workflow["detectedWorkKind"].as_str() == Some("plugin")
        || setup["devTargetKind"].as_str() == Some("plugin")
}

/// Compares the task's customer's expected Dataverse environment label against the active
/// Primarch connection's configured environment label. Returns Some((expected, active)) only
/// when BOTH are set (non-empty, trimmed) and they differ under a case-insensitive comparison —
/// an intentionally opt-in check: tasks/connections that never set a label are not blocked by a
/// check that has nothing to compare against.
fn task_mcp_dataverse_environment_mismatch(
    task: &Value,
    customers: &[Value],
    settings: &Value,
) -> Option<(String, String)> {
    let customer_id = task["customerId"].as_str().unwrap_or("");
    let expected = customers
        .iter()
        .find(|c| c["id"].as_str() == Some(customer_id))
        .and_then(|c| c["dataverseEnvironmentLabel"].as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let active = settings["primarchMcpEnvironmentLabel"]
        .as_str()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    match (expected, active) {
        (Some(e), Some(a)) if !e.eq_ignore_ascii_case(a) => Some((e.to_string(), a.to_string())),
        _ => None,
    }
}

/// Normalizes a raw Dataverse Metadata Check status (from task_mcp_dataverse_check_from_report,
/// or a manual override such as "skipped"/"manually-verified") into the hard-gate status used to
/// decide workflow progression. "warnings" only becomes "passed" once the user has explicitly
/// accepted them (implementationVerification.dataverseCheck.warningsAccepted.accepted) —
/// otherwise it is "warnings_unaccepted" and blocks progression, per the hardening spec.
fn task_mcp_normalize_dataverse_gate(raw_status: &str, warnings_accepted: bool) -> &'static str {
    match raw_status {
        "passed" | "skipped" | "manually-verified" => "passed",
        "warnings" => {
            if warnings_accepted {
                "passed"
            } else {
                "warnings_unaccepted"
            }
        }
        "failed" => "failed",
        "needs_configuration" => "needs_configuration",
        _ => "not_run",
    }
}

/// Evaluates whether a persisted AI Kit review payload (implementationVerification.aiCodeReview)
/// satisfies the hard-gate requirements. There are two independent ways to resolve the gate:
///   1. An automated review with status "passed", empty fixableFindings, and non-empty
///      reviewedFiles/rulesFiles/checklistFiles/knownPrReviewFiles — a "passed" status with
///      missing details is treated as incomplete, not passed.
///   2. An explicit manual UI override ("manually-verified" or "skipped") — these represent an
///      explicit user decision and resolve the gate without requiring the automated detail payload.
/// Returns (gate_status, missing_detail_reasons) where gate_status is one of
/// "passed" | "incomplete" | "failed" | "pending" | "not_run".
fn task_mcp_ai_kit_review_gate(review: &Value) -> (&'static str, Vec<String>) {
    if review.is_null() || !review.is_object() {
        return ("not_run", vec![]);
    }
    let status = review["status"].as_str().unwrap_or("");
    if status.is_empty() {
        return ("not_run", vec![]);
    }
    if matches!(status, "manually-verified" | "skipped") {
        return ("passed", vec![]);
    }
    let has_items = |key: &str| {
        review[key]
            .as_array()
            .map(|a| !a.is_empty())
            .unwrap_or(false)
    };
    let mut missing = Vec::new();
    if !has_items("reviewedFiles") {
        missing.push("reviewedFiles is empty".to_string());
    }
    if !has_items("rulesFiles") {
        missing.push("rulesFiles is empty".to_string());
    }
    if !has_items("checklistFiles") {
        missing.push("checklistFiles is empty".to_string());
    }
    if !has_items("knownPrReviewFiles") {
        missing.push("knownPrReviewFiles is empty".to_string());
    }

    if has_items("fixableFindings") {
        missing.push("fixableFindings is non-empty".to_string());
        return ("failed", missing);
    }
    match status {
        "failed" => ("failed", missing),
        "warnings" => ("pending", missing),
        "passed" => {
            if missing.is_empty() {
                ("passed", vec![])
            } else {
                ("incomplete", missing)
            }
        }
        _ => ("not_run", vec![]),
    }
}

/// Mirrors ImplementationVerificationModal's deriveDataverseCheckStatus (src/components/
/// ImplementationVerificationModal.tsx). Read-only — run_dataverse_check_for_task rejects
/// .js/.ts artifacts, so MCP cannot run this check for script tasks; it can only report the
/// same status the modal would show.
fn task_mcp_derive_dataverse_check_status(task: &Value) -> String {
    let override_status = task["implementationVerification"]["dataverseCheck"]["status"]
        .as_str()
        .unwrap_or("");
    if matches!(
        override_status,
        "skipped" | "manually-verified" | "needs_configuration"
    ) {
        return override_status.to_string();
    }
    let verdict = task["crmVerificationReports"]
        .as_array()
        .and_then(|a| a.first())
        .and_then(|r| r["verdict"].as_str())
        .unwrap_or("");
    match verdict {
        "pass" => "passed".to_string(),
        "warnings" => "warnings".to_string(),
        "fail" => "failed".to_string(),
        "not_configured" => "warnings".to_string(),
        _ => "not-run".to_string(),
    }
}

/// Read-only passthrough for the "Dataverse Metadata Check" modal row. Never writes
/// task.implementationVerification.dataverseCheck — MCP is not the source of truth for this
/// check for script tasks.
fn task_mcp_dataverse_metadata_check_passthrough(task: &Value) -> (String, String) {
    let status = task_mcp_derive_dataverse_check_status(task);
    if task_mcp_impl_check_resolved(&status) {
        (
            status.clone(),
            format!("Existing Dataverse Metadata Check status: {status}."),
        )
    } else {
        (
            "needs_manual_action".to_string(),
            "Run Dataverse Metadata Check in the Implementation Verification modal.".to_string(),
        )
    }
}

/// Read-only passthrough for the "AI Internal Code Review" modal row (task.
/// implementationVerification.aiCodeReview — the LLM-backed AI Kit/Settings Reviewer, distinct
/// from the deterministic staticRules check). MCP cannot invoke a live LLM reviewer headlessly.
fn task_mcp_ai_internal_code_review_passthrough(task: &Value) -> (String, String) {
    let status = task["implementationVerification"]["aiCodeReview"]["status"]
        .as_str()
        .unwrap_or("");
    if task_mcp_impl_check_resolved(status) {
        (
            status.to_string(),
            format!("Existing AI Kit review status: {status}."),
        )
    } else {
        (
            "needs_manual_action".to_string(),
            "Run AI Kit Review or Settings Reviewer in the Implementation Verification modal."
                .to_string(),
        )
    }
}

/// Read-only passthrough for the "Local Test" modal row (task.implementationVerification.
/// localTest — distinct from the top-level task.localTestRecord used by continue_developer_
/// workflow's step 1 gate). record_ai_implementation_completed now writes this field directly
/// for new AI-managed completions; for tasks completed before that write existed, backfill the
/// same derivation here so every read path (modal, workflow overview, run_implementation_
/// verification, get_implementation_verification_summary) agrees.
fn task_mcp_local_test_impl_passthrough(task: &Value) -> (String, String) {
    let status = task["implementationVerification"]["localTest"]["status"]
        .as_str()
        .unwrap_or("");
    if status == "passed" || status == "not-needed" || status == "failed" {
        return (
            status.to_string(),
            format!("Existing Local Test status: {status}."),
        );
    }
    if task_mcp_is_legacy_ai_managed_local_test_not_needed(task) {
        return (
            "not-needed".to_string(),
            "Skipped for AI-managed workflow; no browser/model-driven app test was performed."
                .to_string(),
        );
    }
    ("needs_manual_action".to_string(), "Record Local Test in the Implementation Verification modal after manual/browser CRM testing (or mark it not-needed there).".to_string())
}

/// Called by record_ai_implementation_completed to write the canonical Local Test result for
/// an AI-managed workflow — no browser/model-driven app test was performed, so it is recorded
/// as not-needed, never as passed. Never overwrites an explicit passed/failed result already
/// recorded via the Implementation Verification modal.
fn task_mcp_record_ai_managed_local_test_not_needed(task: &mut Value, now: &str) {
    if !task["implementationVerification"].is_object() {
        task["implementationVerification"] = serde_json::json!({});
    }
    let existing_status = task["implementationVerification"]["localTest"]["status"]
        .as_str()
        .unwrap_or("");
    if existing_status == "passed" || existing_status == "failed" {
        return;
    }
    task["implementationVerification"]["localTest"] = serde_json::json!({
        "status":     "not-needed",
        "recordedAt": now,
        "notes":      "Skipped for AI-managed workflow; no browser/model-driven app test was performed.",
    });
}

/// Compatibility/backfill condition: an AI implementation was completed AND the legacy
/// localTestRecord already marks Local Test as not-needed, but the canonical
/// implementationVerification.localTest field predates record_ai_implementation_completed
/// writing it directly. Ordinary manually managed tasks (no completed AI implementation) never
/// match this and must still show Local Test as not-run/needs_manual_action.
fn task_mcp_is_legacy_ai_managed_local_test_not_needed(task: &Value) -> bool {
    let ai_completed = task["crmDeveloperWorkflow"]["lastAiImplementation"]["completedAt"]
        .as_str()
        .map(|s| !s.is_empty())
        .unwrap_or(false);
    let legacy_not_needed = task["localTestRecord"]["status"].as_str() == Some("not-needed");
    ai_completed && legacy_not_needed
}

/// Normalized, modal-truth verification summary — the same shape regardless of which MCP tool
/// returns it (run_implementation_verification, get_implementation_verification_summary, or
/// get_task_workflow_overview). Built ONLY from the canonical fields ImplementationVerification
/// Modal reads. Never a side-channel-only MCP result. Mirrors JS buildModalVerificationSummary.
fn task_mcp_build_modal_verification_summary(task: &Value) -> Value {
    let build_status = task["implementationVerification"]["buildCheck"]["status"]
        .as_str()
        .unwrap_or("not-run");
    let build_summary = task["implementationVerification"]["buildCheck"]["summary"].as_str();
    let mut build_check =
        serde_json::json!({ "status": build_status, "label": "Script File Readiness" });
    if let Some(summary) = build_summary {
        build_check["message"] = serde_json::json!(summary);
    }

    let (dv_status, dv_message) = task_mcp_dataverse_metadata_check_passthrough(task);
    let (ai_status, ai_message) = task_mcp_ai_internal_code_review_passthrough(task);
    let (lt_status, lt_message) = task_mcp_local_test_impl_passthrough(task);

    serde_json::json!({
        "buildCheck": build_check,
        "dataverseCheck": { "status": dv_status, "label": "Dataverse Metadata Check", "message": dv_message },
        "aiCodeReview": { "status": ai_status, "label": "AI Internal Code Review", "message": ai_message },
        "localTest": { "status": lt_status, "label": "Local Test", "message": lt_message },
    })
}

/// Single source of truth for "can this task move to Code Review / Waiting for PR". Computed
/// from the exact same fields (implementationVerification.dataverseCheck /
/// implementationVerification.aiCodeReview) that MCP's run_implementation_verification and the
/// UI's Implementation Verification modal both read/write, so the MCP-facing workflow and the
/// human-facing "Move to Code Review" button enforce identical rules. Exposed to the frontend via
/// the get_implementation_progression_gate Tauri command. Pure — no I/O.
fn task_mcp_compute_progression_gate(task: &Value) -> Value {
    let dv_raw = task_mcp_derive_dataverse_check_status(task);
    let dv_warnings_accepted = task_mcp_dataverse_warnings_accepted(task);
    let dv_gate = task_mcp_normalize_dataverse_gate(&dv_raw, dv_warnings_accepted);

    let ai_review = task["implementationVerification"]["aiCodeReview"].clone();
    let (ai_gate, ai_missing) = task_mcp_ai_kit_review_gate(&ai_review);

    let mut blocking_checks: Vec<Value> = Vec::new();
    let mut blocking_findings: Vec<Value> = Vec::new();

    match dv_gate {
        "passed" => {}
        "warnings_unaccepted" => blocking_checks.push(serde_json::json!({
            "check": "dataverseCheck", "status": dv_gate,
            "reason": "Dataverse Metadata Check completed with warnings that have not been explicitly accepted.",
        })),
        "needs_configuration" => blocking_checks.push(serde_json::json!({
            "check": "dataverseCheck", "status": dv_gate,
            "reason": "Dataverse Metadata Check cannot run — Primarch/Dataverse connection is not configured or does not match the task's environment.",
        })),
        "failed" => {
            let missing_refs = task["crmVerificationReports"][0]["missingReferences"].as_array().cloned().unwrap_or_default();
            for m in &missing_refs {
                let label = m["displayName"].as_str().unwrap_or("unknown");
                blocking_findings.push(serde_json::json!({ "check": "dataverseCheck", "description": format!("'{label}' was not found in Dataverse.") }));
            }
            blocking_checks.push(serde_json::json!({
                "check": "dataverseCheck", "status": dv_gate,
                "reason": "Dataverse Metadata Check found missing/incorrect references.",
            }));
        }
        _ => blocking_checks.push(serde_json::json!({
            "check": "dataverseCheck", "status": dv_gate,
            "reason": "Dataverse Metadata Check has not run yet.",
        })),
    }

    match ai_gate {
        "passed" => {}
        "failed" => {
            for f in ai_review["fixableFindings"].as_array().cloned().unwrap_or_default() {
                blocking_findings.push(serde_json::json!({ "check": "aiCodeReview", "description": f["description"].clone() }));
            }
            blocking_checks.push(serde_json::json!({
                "check": "aiCodeReview", "status": ai_gate,
                "reason": "AI Kit Code Review found fixable findings or an explicit failed verdict.",
            }));
        }
        "incomplete" => blocking_checks.push(serde_json::json!({
            "check": "aiCodeReview", "status": ai_gate,
            "reason": format!("AI Kit Code Review is missing required details: {}.", ai_missing.join(", ")),
        })),
        "pending" => blocking_checks.push(serde_json::json!({
            "check": "aiCodeReview", "status": ai_gate,
            "reason": "AI Kit Code Review verdict is 'warnings' — must be resolved to 'passed'.",
        })),
        _ => blocking_checks.push(serde_json::json!({
            "check": "aiCodeReview", "status": ai_gate,
            "reason": "AI Kit Code Review has not run yet.",
        })),
    }

    let can_proceed = blocking_checks.is_empty();
    let requires_user_action = matches!(dv_gate, "warnings_unaccepted" | "needs_configuration");
    let next_recommended_action = if can_proceed {
        "continue_workflow"
    } else if !blocking_findings.is_empty() {
        "fix_code"
    } else if matches!(ai_gate, "incomplete" | "pending" | "not_run") {
        "run_ai_kit_review"
    } else if dv_gate == "needs_configuration" {
        "needs_configuration"
    } else if dv_gate == "warnings_unaccepted" {
        "review_dataverse_warnings"
    } else {
        "wait_for_user"
    };

    serde_json::json!({
        "canProceed": can_proceed,
        "blockingChecks": blocking_checks,
        "blockingFindings": blocking_findings,
        "requiresUserAction": requires_user_action,
        "nextRecommendedAction": next_recommended_action,
        "dataverseGateStatus": dv_gate,
        "aiReviewGateStatus": ai_gate,
    })
}

/// Keys of the modal-required rows still unresolved (needs_manual_action or genuinely not-run).
fn task_mcp_unresolved_modal_rows(summary: &Value) -> Vec<String> {
    let unresolved = |row: &Value| {
        matches!(
            row["status"].as_str(),
            Some("needs_manual_action") | Some("not-run")
        )
    };
    let mut rows = Vec::new();
    if unresolved(&summary["dataverseCheck"]) {
        rows.push("dataverseCheck".to_string());
    }
    if unresolved(&summary["aiCodeReview"]) {
        rows.push("aiCodeReview".to_string());
    }
    if unresolved(&summary["localTest"]) {
        rows.push("localTest".to_string());
    }
    rows
}

/// Composes the single, complete manual-action message used by continue_developer_workflow,
/// get_task_workflow_overview.nextRecommendedStep, run_implementation_verification, and (in JS)
/// the Implementation Verification modal footer — so all four always say the same thing. Only
/// mentions the checks that are actually still unresolved.
fn task_mcp_compose_manual_verification_step(summary: &Value) -> String {
    let needs = |row: &Value| {
        matches!(
            row["status"].as_str(),
            Some("needs_manual_action") | Some("not-run")
        )
    };
    let dv_needs = needs(&summary["dataverseCheck"]);
    let ai_needs = needs(&summary["aiCodeReview"]);

    let mut modal_names: Vec<&str> = Vec::new();
    if dv_needs {
        modal_names.push("Dataverse Metadata Check");
    }
    if ai_needs {
        modal_names.push("AI Kit/Settings Review");
    }

    if modal_names.is_empty() {
        "All Implementation Verification checks are resolved.".to_string()
    } else {
        format!(
            "Run {} in the Implementation Verification modal.",
            modal_names.join(" and ")
        )
    }
}

// ---------------------------------------------------------------------------
// Deployment & Testing gate — mirrors src/lib/deploymentTestingGate.ts
// (computeDeploymentTestingGate, computeCodeReviewReadinessGate) and
// computeDeploymentTestingGate/computeCodeReviewReadinessGate in mcp/task-workbench-mcp.mjs.
// Deliberately never reads implementationVerification.localTest, localTestRecord, or
// consultantTestRecord — those predate the artifact ever being deployed.
// ---------------------------------------------------------------------------

fn task_mcp_derive_manual_deployment_status(task: &Value) -> String {
    task["deploymentTesting"]["deployment"]["status"]
        .as_str()
        .unwrap_or("not-run")
        .to_string()
}

fn task_mcp_derive_deployment_test_status(task: &Value) -> String {
    task["deploymentTesting"]["test"]["status"]
        .as_str()
        .unwrap_or("not-run")
        .to_string()
}

/// Single source of truth for "can this task proceed to Commit & Push". Pure — no I/O.
fn task_mcp_compute_deployment_testing_gate(task: &Value) -> Value {
    let deployment_status = task_mcp_derive_manual_deployment_status(task);
    let test_status = task_mcp_derive_deployment_test_status(task);
    let mut blocking_checks: Vec<Value> = Vec::new();

    let deployment_resolved = deployment_status == "deployed" || deployment_status == "not-needed";
    if !deployment_resolved {
        blocking_checks.push(serde_json::json!({
            "check": "deployment", "status": deployment_status,
            "reason": if deployment_status == "failed" {
                "Manual deployment was recorded as failed. Redeploy and record the result before testing."
            } else {
                "Manual deployment has not been recorded yet."
            },
        }));
    }
    if deployment_resolved {
        if test_status == "failed" {
            blocking_checks.push(serde_json::json!({
                "check": "test", "status": test_status,
                "reason": "Deployment test failed. Fix the code or redeploy, then record a new test result.",
            }));
        } else if test_status == "not-run" {
            blocking_checks.push(serde_json::json!({
                "check": "test", "status": test_status,
                "reason": "Browser/model-driven app test has not been recorded yet.",
            }));
        }
    }

    let can_proceed_to_commit = blocking_checks.is_empty();
    let next_recommended_action = if can_proceed_to_commit {
        "prepare_commit"
    } else if !deployment_resolved {
        "wait_for_manual_deployment"
    } else if test_status == "failed" {
        "fix_code_or_redeploy"
    } else {
        "wait_for_deployment_test"
    };

    serde_json::json!({
        "canProceedToCommit": can_proceed_to_commit,
        "deploymentStatus": deployment_status,
        "testStatus": test_status,
        "blockingChecks": blocking_checks,
        "nextRecommendedAction": next_recommended_action,
    })
}

/// Shared record_manual_deployment/record_deployment_test validation: a successful outcome
/// ('deployed'/'passed') or 'failed' is a one-click confirmation and never requires notes; only
/// the 'not-needed' override requires a real, non-empty user-provided reason. Pure — no I/O.
fn task_mcp_validate_not_needed_requires_notes(status: &str, notes: &str) -> Result<(), String> {
    if status == "not-needed" && notes.trim().is_empty() {
        Err(format!(
            "notes is required and must be meaningful when recording status='{status}'"
        ))
    } else {
        Ok(())
    }
}

/// Blocks commit/push tools from advancing the workflow when the Deployment & Testing gate is
/// unresolved. Read-only Git diagnostics (prepare_commit_for_task, reconcile_task_git_state) are
/// still allowed — only actual commit/push mutations are rejected here.
fn task_mcp_require_deployment_testing_gate_resolved(task: &Value) -> Result<(), String> {
    let gate = task_mcp_compute_deployment_testing_gate(task);
    if gate["canProceedToCommit"].as_bool().unwrap_or(false) {
        Ok(())
    } else {
        let reason = gate["blockingChecks"][0]["reason"]
            .as_str()
            .unwrap_or("Deployment & Testing is not resolved yet.");
        Err(format!(
            "Cannot commit/push: {reason} Record manual deployment and a browser/application test \
             result (record_manual_deployment, record_deployment_test) before committing."
        ))
    }
}

/// Single source of truth for "can this task enter Code Review / waiting for colleague review".
/// Requires a verified local commit, a verified push of that same branch, and an explicitly
/// created/recorded pull request — never satisfied by an AI/Claude code review alone.
fn task_mcp_compute_code_review_readiness_gate(task: &Value) -> Value {
    let gw = &task["gitWorkflow"];
    let commit_verified = gw["lastCommitHash"]
        .as_str()
        .map(|s| !s.is_empty())
        .unwrap_or(false);
    let last_pushed_branch = gw["lastPushedBranch"].as_str().filter(|s| !s.is_empty());
    let last_commit_branch = gw["lastCommitBranch"].as_str().filter(|s| !s.is_empty());
    let push_verified = last_pushed_branch.is_some()
        && !gw["lastPushedAt"].is_null()
        && (last_commit_branch.is_none() || last_pushed_branch == last_commit_branch);

    let pr_tracking = &task["crmDeveloperWorkflow"]["pullRequestTracking"];
    let pr_recorded = pr_tracking["createdManually"].as_bool().unwrap_or(false)
        && pr_tracking["prUrl"]
            .as_str()
            .map(|s| !s.is_empty())
            .unwrap_or(false)
        && pr_tracking["invalidatedAt"].is_null();

    let can_enter_code_review = commit_verified && push_verified && pr_recorded;
    let next_recommended_action = if can_enter_code_review {
        "wait_for_colleague_code_review"
    } else if !commit_verified || !push_verified {
        "commit_and_push"
    } else {
        "prepare_pull_request"
    };

    serde_json::json!({
        "canEnterCodeReview": can_enter_code_review,
        "commitVerified": commit_verified,
        "pushVerified": push_verified,
        "prRecorded": pr_recorded,
        "nextRecommendedAction": next_recommended_action,
    })
}

/// continue_developer_workflow nextAction values that mean "the task is now (or already) in the
/// Deployment & Testing phase". Kept in sync with DEPLOYMENT_TESTING_NEXT_ACTIONS in
/// mcp/task-workbench-mcp.mjs.
const DEPLOYMENT_TESTING_NEXT_ACTIONS: &[&str] = &[
    "wait_for_manual_deployment",
    "wait_for_deployment_test",
    "fix_code_or_redeploy",
];

/// Pure decision: should this continue_developer_workflow call persist the Development ->
/// Deployment & Testing transition? True exactly when the computed nextAction indicates the
/// Deployment & Testing phase and the task has not already transitioned (idempotent — a repeated
/// call while still waiting on manual deployment/testing, or once past it to commit/push/PR, is a
/// no-op here). Pure — no I/O.
fn task_mcp_should_transition_to_deployment_testing(task: &Value, next_action: &str) -> bool {
    DEPLOYMENT_TESTING_NEXT_ACTIONS.contains(&next_action)
        && task["waitingState"].as_str() != Some("consultant-testing")
}

/// Applies the Development -> Deployment & Testing transition to `task` in place, when
/// task_mcp_should_transition_to_deployment_testing says to. This is the SAME local-only mutation
/// the "Continue to Deployment & Testing" UI button performs (waitingState only; status untouched)
/// — never Git, filesystem, Dataverse, deployment, commit, push, or PR. Pure with respect to
/// everything except `task` — no AppHandle, no task-list lookup, no save; the
/// "continue_developer_workflow" tool arm is the only caller that persists the change afterward.
/// Returns true when the transition was actually applied.
fn task_mcp_apply_deployment_testing_transition(task: &mut Value, next_action: &str) -> bool {
    if !task_mcp_should_transition_to_deployment_testing(task, next_action) {
        return false;
    }
    task["waitingState"] = serde_json::json!("consultant-testing");
    task["attentionState"] = Value::Null;
    task_mcp_append_audit_note(
        task,
        &format!(
            "continue_developer_workflow -> transitioned to Deployment & Testing ({next_action})"
        ),
    );
    true
}

fn task_mcp_compute_continue_workflow_step(task: &Value) -> Value {
    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let work_kind = workflow["detectedWorkKind"]
        .as_str()
        .or_else(|| setup["devTargetKind"].as_str())
        .unwrap_or("unknown");
    let is_script = task_mcp_is_verifiable_dev_task(task);
    let _ = work_kind;

    // 1. Dataverse verification. (Local Test is NOT part of Implementation Verification — the
    // legacy localTestRecord/implementationVerification.localTest fields are never read as a gate
    // here; see task_mcp_compute_deployment_testing_gate below for the canonical post-deployment
    // test gate.)
    let dv_check = &task["implementationVerification"]["dataverseCheck"];
    let first_verdict = task["crmVerificationReports"]
        .as_array()
        .and_then(|a| a.first())
        .and_then(|r| r["verdict"].as_str())
        .unwrap_or("");
    let dv_done = !dv_check["skippedAt"].is_null()
        || !dv_check["manuallyVerifiedAt"].is_null()
        || matches!(
            dv_check["status"].as_str().unwrap_or(""),
            "skipped" | "done" | "manually-verified"
        )
        || matches!(first_verdict, "pass" | "warnings" | "fail");
    if !dv_done {
        if is_script {
            let mcp_verification = &task["implementationVerification"]["mcpVerification"];
            if mcp_verification["ranAt"].is_null() {
                return serde_json::json!({
                    "nextAction": "run_implementation_verification",
                    "canProceed": true,
                    "requiresUserApproval": false,
                    "blockingUserAction": null,
                    "recommendedTool": "run_implementation_verification",
                    "instructionForAI": "Run run_implementation_verification. It automatically runs Dataverse Metadata Check (when Primarch is configured) and reports whether AI Kit review is still needed — only the final manual upload/register/browser Local Test step requires waiting for the user.",
                    "allowedWrites": ["run_implementation_verification"],
                    "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
                });
            }
            let mcp_verification_failed_with_fixes = mcp_verification["status"].as_str()
                == Some("failed")
                && mcp_verification["fixableFindings"]
                    .as_array()
                    .map(|a| !a.is_empty())
                    .unwrap_or(false);
            if mcp_verification_failed_with_fixes {
                return serde_json::json!({
                    "nextAction": "fix_code",
                    "canProceed": true,
                    "requiresUserApproval": false,
                    "blockingUserAction": null,
                    "recommendedTool": "record_ai_implementation_completed",
                    "instructionForAI": "Fix the fixable findings from run_implementation_verification, then call record_ai_implementation_completed and run_implementation_verification again.",
                    "allowedWrites": ["record_ai_implementation_completed", "run_implementation_verification"],
                    "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
                });
            }
            if mcp_verification["status"].as_str() == Some("pending_ai_kit_review") {
                return serde_json::json!({
                    "nextAction": "run_ai_kit_review",
                    "canProceed": true,
                    "requiresUserApproval": false,
                    "blockingUserAction": null,
                    "recommendedTool": "record_ai_kit_review_result",
                    "instructionForAI": "Dataverse Metadata Check is resolved. Read the applicable AI Kit rules and the target file yourself, then call record_ai_kit_review_result with your verdict, then call run_implementation_verification again.",
                    "allowedWrites": ["record_ai_kit_review_result", "run_implementation_verification"],
                    "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
                });
            }
            if mcp_verification["status"].as_str() == Some("needs_configuration") {
                let reason = mcp_verification["checks"]
                    .as_array()
                    .and_then(|checks| {
                        checks
                            .iter()
                            .find(|c| c["status"].as_str() == Some("needs_configuration"))
                    })
                    .and_then(|c| c["findings"][0].as_str())
                    .unwrap_or("Dataverse Metadata Check is not configured.")
                    .to_string();
                return serde_json::json!({
                    "nextAction": "needs_configuration",
                    "canProceed": false,
                    "requiresUserApproval": true,
                    "blockingUserAction": reason,
                    "recommendedTool": null,
                    "instructionForAI": format!("{reason} This cannot be resolved by the AI agent — ask the user to configure it, then call continue_developer_workflow again."),
                    "allowedWrites": [],
                    "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
                });
            }
            if mcp_verification["status"].as_str() == Some("warnings_unaccepted") {
                let reason = "Dataverse Metadata Check completed with warnings that have not been explicitly accepted yet.".to_string();
                return serde_json::json!({
                    "nextAction": "review_dataverse_warnings",
                    "canProceed": false,
                    "requiresUserApproval": true,
                    "blockingUserAction": reason,
                    "recommendedTool": null,
                    "instructionForAI": format!("{reason} This requires the user: ask them to review the warnings in the Implementation Verification modal and either accept them and continue, or send the task back for you to fix the code and rerun the check."),
                    "allowedWrites": [],
                    "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
                });
            }
            if mcp_verification["status"].as_str() == Some("needs_manual_action") {
                let manual_step = task_mcp_compose_manual_verification_step(
                    &task_mcp_build_modal_verification_summary(task),
                );
                return serde_json::json!({
                    "nextAction": "wait_for_user",
                    "canProceed": false,
                    "requiresUserApproval": true,
                    "blockingUserAction": manual_step,
                    "recommendedTool": null,
                    "instructionForAI": format!(
                        "Script File Readiness and local static/business-rule verification are complete, but some Implementation Verification modal rows are still not-run. {manual_step} Call continue_developer_workflow again after the user completes it."
                    ),
                    "allowedWrites": [],
                    "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
                });
            }
            // Fallback (should be rare): Dataverse Metadata Check ran but did not resolve.
            // Re-run run_implementation_verification rather than pointing at the in-app modal —
            // the automated check can be retried directly.
            return serde_json::json!({
                "nextAction": "run_implementation_verification",
                "canProceed": true,
                "requiresUserApproval": false,
                "blockingUserAction": null,
                "recommendedTool": "run_implementation_verification",
                "instructionForAI": "Dataverse Metadata Check has not resolved yet. Call run_implementation_verification again.",
                "allowedWrites": ["run_implementation_verification"],
                "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
            });
        }
        return serde_json::json!({
            "nextAction": "verify_dataverse",
            "canProceed": true,
            "requiresUserApproval": false,
            "blockingUserAction": null,
            "recommendedTool": "run_dataverse_check_for_task",
            "instructionForAI": "Run Dataverse metadata verification using run_dataverse_check_for_task, then call continue_developer_workflow again.",
            "allowedWrites": ["run_dataverse_check_for_task"],
            "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
        });
    }

    // 3. AI Kit review — hard gate. Reads implementationVerification.aiCodeReview (the canonical
    // field the modal reads), NOT the looser task.aiKitReview.completedAt flag: recording ANY
    // verdict (including "failed") always sets completedAt, so gating on completedAt alone would
    // let a failed/incomplete review through. task_mcp_ai_kit_review_gate resolves via either an
    // automated status=="passed" review with fixableFindings empty AND reviewedFiles/rulesFiles/
    // checklistFiles/knownPrReviewFiles all non-empty, OR an explicit manual UI override
    // (status=="manually-verified" or "skipped", which record_ai_kit_review_result itself cannot
    // set — see its input schema status enum).
    let ai_review = &task["implementationVerification"]["aiCodeReview"];
    let (ai_gate, ai_missing) = task_mcp_ai_kit_review_gate(ai_review);
    if ai_gate != "passed" {
        let instruction = match ai_gate {
            "failed" => "AI Kit review found fixable findings or has an explicit 'failed' verdict. Fix the code, then call record_ai_kit_review_result again with status='passed' and full review details, then call continue_developer_workflow again.".to_string(),
            "incomplete" => format!("AI Kit review was recorded as 'passed' but is missing required details: {}. Call record_ai_kit_review_result again including reviewedFiles, rulesFiles, checklistFiles, and knownPrReviewFiles, then call continue_developer_workflow again.", ai_missing.join(", ")),
            "pending" => "AI Kit review verdict is 'warnings' — resolve the warnings, then call record_ai_kit_review_result again with status='passed', then call continue_developer_workflow again.".to_string(),
            _ => "AI Kit review is required before branch creation. Read the applicable AI Kit rules, the CRM code review checklist, known PR review comments, and the target file yourself, then call record_ai_kit_review_result with your verdict and full review details, then call continue_developer_workflow again.".to_string(),
        };
        return serde_json::json!({
            "nextAction": "run_ai_kit_review",
            "canProceed": true,
            "requiresUserApproval": false,
            "blockingUserAction": null,
            "recommendedTool": "record_ai_kit_review_result",
            "instructionForAI": instruction,
            "allowedWrites": ["record_ai_kit_review_result", "record_ai_implementation_completed"],
            "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
        });
    }

    // 4. Deployment & Testing — local Task Workbench state only (record_manual_deployment /
    // record_deployment_test never call Dataverse/Git/PAC CLI). Resolved only via the canonical
    // deploymentTesting field — never the legacy localTestRecord/implementationVerification.
    // localTest/consultantTestRecord fields.
    let deployment_gate = task_mcp_compute_deployment_testing_gate(task);
    if !deployment_gate["canProceedToCommit"]
        .as_bool()
        .unwrap_or(false)
    {
        let next = deployment_gate["nextRecommendedAction"]
            .as_str()
            .unwrap_or("");
        if next == "wait_for_manual_deployment" {
            return serde_json::json!({
                "nextAction": "wait_for_manual_deployment",
                "canProceed": false,
                "requiresUserApproval": true,
                "blockingUserAction": "Ask the user to manually deploy the CRM artifact (Dataverse/Power Apps import, web resource publish, form registration, etc.), then record it with record_manual_deployment.",
                "recommendedTool": null,
                "instructionForAI": "Implementation Verification passed, but this is a local-only code/metadata gate — the artifact has not been deployed yet. Stop and ask the user to deploy it manually. Never call record_manual_deployment speculatively or because static verification passed; only after the user confirms the deployment actually happened, with meaningful notes describing what was done.",
                "allowedWrites": ["record_manual_deployment"],
                "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes", "record_deployment_test"],
            });
        }
        if next == "fix_code_or_redeploy" {
            return serde_json::json!({
                "nextAction": "fix_code_or_redeploy",
                "canProceed": true,
                "requiresUserApproval": false,
                "blockingUserAction": null,
                "recommendedTool": null,
                "instructionForAI": "The deployment test was recorded as failed. Fix the code, or ask the user to redeploy, then wait for a new test result via record_deployment_test — do not proceed to commit/push.",
                "allowedWrites": [],
                "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
            });
        }
        return serde_json::json!({
            "nextAction": "wait_for_deployment_test",
            "canProceed": false,
            "requiresUserApproval": true,
            "blockingUserAction": "Ask the user to perform a real browser/model-driven app test of the deployed artifact, then record it with record_deployment_test.",
            "recommendedTool": null,
            "instructionForAI": "Manual deployment is recorded. Stop and ask the user to test the deployed artifact in the browser/model-driven app. Never call record_deployment_test unless the user confirms a real test was actually performed.",
            "allowedWrites": ["record_deployment_test"],
            "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
        });
    }

    // 5. Commit verified? Push verified? Pull request created/recorded? Each is a separate,
    // explicit user approval — approving one is never approval for the next.
    let review_readiness = task_mcp_compute_code_review_readiness_gate(task);
    let commit_verified = review_readiness["commitVerified"]
        .as_bool()
        .unwrap_or(false);
    let push_verified = review_readiness["pushVerified"].as_bool().unwrap_or(false);
    let pr_recorded = review_readiness["prRecorded"].as_bool().unwrap_or(false);
    if commit_verified && push_verified && pr_recorded {
        return serde_json::json!({
            "nextAction": "wait_for_colleague_code_review",
            "canProceed": true,
            "requiresUserApproval": true,
            "blockingUserAction": "Waiting for a colleague to review the pull request.",
            "recommendedTool": null,
            "instructionForAI": "Commit, push, and pull request are all verified. Stop and report that the task is waiting for colleague code review. This is independent of any AI/Claude review performed earlier (record_ai_kit_review_result) — never call your own review an independent colleague review.",
            "allowedWrites": [],
            "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes", "record_pull_request_created"],
        });
    }
    if commit_verified && push_verified {
        return serde_json::json!({
            "nextAction": "prepare_pull_request",
            "canProceed": true,
            "requiresUserApproval": true,
            "blockingUserAction": "Ask the user for a SEPARATE explicit approval before creating or recording a pull request — approval to commit/push is not approval to create a PR.",
            "recommendedTool": "prepare_pull_request_for_task",
            "instructionForAI": "Commit and push are verified. Call prepare_pull_request_for_task to preview the PR (branches, title, description, detected existing PR). Ask the user for a separate explicit approval before creating or recording a pull request. If automatic creation is unavailable for this provider, give manual instructions and record the result with record_pull_request_created only with a real PR URL the user (or you, after approval) actually created — never fabricate one.",
            "allowedWrites": ["prepare_pull_request_for_task", "record_pull_request_created"],
            "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
        });
    }
    if commit_verified {
        return serde_json::json!({
            "nextAction": "commit_and_push",
            "canProceed": true,
            "requiresUserApproval": true,
            "blockingUserAction": "Ask the user for a SEPARATE explicit approval before pushing.",
            "recommendedTool": "push_task_branch",
            "instructionForAI": "A commit is verified locally but not yet pushed. Ask the user for a separate explicit approval, then call push_task_branch or commit_and_push_task_changes.",
            "allowedWrites": ["push_task_branch", "commit_and_push_task_changes"],
            "forbiddenWrites": [],
        });
    }

    // 6. Propose/confirm branch, then commit — each step requires its OWN explicit user
    // approval. Confirming a branch name does not imply the commit is approved, and vice versa.
    let confirmed_branch = task["gitWorkflow"]["confirmedBranch"]
        .as_str()
        .filter(|s| !s.is_empty());
    if let Some(branch) = confirmed_branch {
        return serde_json::json!({
            "nextAction": "prepare_commit",
            "canProceed": true,
            "requiresUserApproval": true,
            "blockingUserAction": "Ask the user to confirm the commit (files + message) before committing.",
            "recommendedTool": "prepare_commit_for_task",
            "instructionForAI": format!(
                "Branch '{branch}' was already created/checked out and confirmed. Call prepare_commit_for_task to show the user exactly what would be committed (changed files, ignored/gitignored files, suggested message), then ask for a SEPARATE explicit approval of the commit itself before calling commit_task_changes. Do not call push_task_branch or commit_and_push_task_changes without a further separate approval to push."
            ),
            "allowedWrites": ["prepare_commit_for_task", "commit_task_changes"],
            "forbiddenWrites": ["push_task_branch", "commit_and_push_task_changes"],
        });
    }

    serde_json::json!({
        "nextAction": "propose_branch",
        "canProceed": true,
        "requiresUserApproval": true,
        "blockingUserAction": "Ask the user to confirm the proposed branch name before creating/checking it out.",
        "recommendedTool": "create_or_checkout_task_branch",
        "instructionForAI": "Implementation, verification, and AI Kit review are complete. Call prepare_commit_for_task to get a suggested branch name (proposedBranchName) and see whether it already exists (branchExists), propose that name to the user, and ask them to confirm the exact branch name. Once the user approves, call create_or_checkout_task_branch with mode='create_if_missing_and_checkout' to actually create/check out the branch — prepare_commit_for_task alone never creates or checks out anything. Do not call commit_task_changes, push_task_branch, or commit_and_push_task_changes until a SEPARATE explicit approval of the commit itself, after the branch exists.",
        "allowedWrites": ["prepare_commit_for_task", "create_or_checkout_task_branch"],
        "forbiddenWrites": ["commit_task_changes", "push_task_branch", "commit_and_push_task_changes"],
    })
}

fn task_mcp_implementation_readiness(task: &Value) -> Value {
    let mode = task["taskMode"].as_str().unwrap_or("");
    if mode != "developer" {
        return serde_json::json!({
            "isImplementationReady": false,
            "blockers": ["Task mode is not set to Developer."],
            "warnings": [],
            "recommendedNextStep": "Set task mode to Developer.",
        });
    }

    let setup = task.get("workflowSetup").unwrap_or(&Value::Null);
    let workflow = task.get("crmDeveloperWorkflow").unwrap_or(&Value::Null);
    let detected = workflow["detectedWorkKind"].as_str().unwrap_or("");
    let dev_kind = setup["devTargetKind"].as_str().unwrap_or("");

    let is_plugin = dev_kind == "plugin" || detected == "plugin";
    let is_script = dev_kind == "script" || detected == "script" || detected == "ribbon";

    if !is_plugin && !is_script {
        let title = task["title"].as_str().unwrap_or("").to_lowercase();
        let original = task["originalMessage"]
            .as_str()
            .unwrap_or("")
            .to_lowercase();
        let label = task["classificationLabel"]
            .as_str()
            .unwrap_or("")
            .to_lowercase();
        let corpus = format!("{} {} {}", title, original, label);
        let looks_script = corpus.contains("javascript")
            || corpus.contains("form script")
            || corpus.contains("web resource")
            || corpus.contains("jscript")
            || corpus.contains("on load")
            || corpus.contains("onload")
            || corpus.contains("on save")
            || corpus.contains("onsave")
            || corpus.contains("field change")
            || corpus.contains("column change")
            || corpus.contains("onchange");
        let warnings_val: Vec<&str> = if looks_script {
            vec!["Task text mentions JavaScript/form scripts. Consider classifying this task as script work kind."]
        } else {
            vec![]
        };
        let next_step = if looks_script {
            "Set work classification to script (JavaScript form script indicators found in task text)."
        } else {
            "Set work classification to plugin or script via Set Work Classification."
        };
        return serde_json::json!({
            "isImplementationReady": false,
            "blockers": ["Work kind must be plugin or script."],
            "warnings": warnings_val,
            "recommendedNextStep": next_step,
        });
    }

    let mut blockers: Vec<String> = Vec::new();
    let mut warnings: Vec<String> = Vec::new();

    let customer = setup["customerId"]
        .as_str()
        .or(task["customerId"].as_str())
        .unwrap_or("");
    if customer.is_empty() {
        blockers.push("Customer/environment is not set.".into());
    }

    if setup["repositoryRoot"].as_str().unwrap_or("").is_empty() {
        blockers.push("Repository root is not set.".into());
    }
    if setup["confirmedAt"].as_str().unwrap_or("").is_empty() {
        blockers.push("Developer setup has not been confirmed.".into());
    }

    let has_plan = workflow
        .get("technicalPlan")
        .map(|p| p.is_object())
        .unwrap_or(false);
    if !has_plan {
        blockers.push("Technical implementation plan is missing.".into());
    }

    let latest_verdict = task
        .get("crmVerificationReports")
        .and_then(|r| r.as_array())
        .and_then(|arr| arr.first())
        .and_then(|r| r["verdict"].as_str())
        .unwrap_or("");
    let dv_check = task
        .get("implementationVerification")
        .and_then(|v| v.get("dataverseCheck"))
        .unwrap_or(&Value::Null);
    let dv_satisfied = matches!(latest_verdict, "pass" | "warnings" | "fail")
        || !dv_check["skippedAt"].is_null()
        || !dv_check["manuallyVerifiedAt"].is_null()
        || dv_check["status"]
            .as_str()
            .map(|s| s == "skipped" || s == "manually-verified")
            .unwrap_or(false);

    if !dv_satisfied {
        if is_script {
            warnings.push("Dataverse metadata verification for JS/TS runs automatically after implementation via run_implementation_verification (Primarch, when configured) — not before.".into());
        } else {
            blockers.push(
                "Dataverse metadata verification has not been completed or explicitly skipped."
                    .into(),
            );
        }
    } else {
        if latest_verdict == "warnings" {
            warnings.push(
                "Dataverse verification completed with warnings. Review before implementing."
                    .into(),
            );
        }
        if latest_verdict == "fail" {
            warnings.push("Dataverse verification found issues. Ensure they are accounted for in the technical plan.".into());
        }
    }

    let plan_target = if has_plan {
        workflow
            .get("technicalPlan")
            .and_then(|p| p.get("target"))
            .unwrap_or(&Value::Null)
    } else {
        &Value::Null
    };

    if is_plugin {
        let plugin_project = setup["pluginProject"]
            .as_str()
            .or(task["selectedPluginProject"].as_str())
            .or(plan_target["pluginProject"].as_str())
            .unwrap_or("");
        if plugin_project.is_empty() {
            blockers.push("Plugin project is not selected.".into());
        }

        let entity = setup["primaryEntityLogicalName"]
            .as_str()
            .or(plan_target["entityLogicalName"].as_str())
            .unwrap_or("");
        if entity.is_empty() {
            blockers.push("Target entity logical name is not set.".into());
        }

        if has_plan {
            let mut missing: Vec<&str> = Vec::new();
            if plan_target["message"].as_str().unwrap_or("").is_empty() {
                missing.push("message");
            }
            if plan_target["stage"].as_str().unwrap_or("").is_empty() {
                missing.push("stage");
            }
            if plan_target["mode"].as_str().unwrap_or("").is_empty() {
                missing.push("mode");
            }
            if !missing.is_empty() {
                blockers.push(format!("Plugin registration details are incomplete: {} not specified in technical plan.", missing.join(", ")));
            }
        }
    }

    if is_script {
        let artifact = setup["artifactPath"].as_str().unwrap_or("");
        let setup_path = setup["scriptPath"].as_str().unwrap_or("");
        let plan_path = plan_target["scriptPath"].as_str().unwrap_or("");
        let target_path = if !artifact.is_empty() {
            artifact
        } else if !setup_path.is_empty() {
            setup_path
        } else {
            plan_path
        };

        if target_path.is_empty() {
            blockers.push("Target script/artifact path is not set.".into());
        } else {
            let action_type = setup["actionType"].as_str().unwrap_or("");
            let is_specific = |p: &str| -> bool {
                p.ends_with(".js")
                    || p.ends_with(".ts")
                    || p.ends_with(".jsx")
                    || p.ends_with(".tsx")
            };

            if action_type == "create-new-script" {
                // Mirrors mcp/task-workbench-mcp.mjs computeImplementationReadiness's hasDir
                // exactly: artifactPath alone is sufficient, it does not also require the
                // separate bare scriptPath (folder) field or a plan.target.scriptPath. A
                // customer without an explicit scriptFolder never populates workflowSetup.
                // scriptPath even once artifactPath is correctly resolved from the template.
                let has_dir = !artifact.is_empty() || !setup_path.is_empty();
                let desired_file = setup["desiredScriptFile"].as_str().unwrap_or("");
                let has_filename = !artifact.is_empty()
                    || is_specific(setup_path)
                    || is_specific(plan_path)
                    || !desired_file.is_empty();
                if !has_dir || !has_filename {
                    blockers.push("Script creation requires a known target directory and file name. Set script path and desired file name.".into());
                }
            } else if action_type == "update-existing-script" {
                let has_specific =
                    !artifact.is_empty() || is_specific(setup_path) || is_specific(plan_path);
                if !has_specific {
                    blockers.push("Script update requires a specific existing file path. Set script path to an existing .js file.".into());
                }
            }
        }

        let entity = setup["primaryEntityLogicalName"]
            .as_str()
            .or(plan_target["entityLogicalName"].as_str())
            .unwrap_or("");
        if entity.is_empty() {
            blockers.push("Target entity logical name (table) is not set.".into());
        }

        if has_plan {
            let has_form_event = !plan_target["formName"].as_str().unwrap_or("").is_empty()
                || !plan_target["eventName"].as_str().unwrap_or("").is_empty()
                || !plan_target["eventFieldName"]
                    .as_str()
                    .unwrap_or("")
                    .is_empty()
                || !plan_target["functionName"]
                    .as_str()
                    .unwrap_or("")
                    .is_empty();
            let manual_later = setup["scriptFormRegistration"]
                .as_str()
                .map(|s| s == "manual-later")
                .unwrap_or(false);
            if !has_form_event && !manual_later {
                blockers.push("Form/event registration details are not set. Add form name, event name, or mark as manual registration later.".into());
            }
        }
    }

    let is_ready = blockers.is_empty();
    let recommended: String = if is_ready {
        if !warnings.is_empty() {
            "Review warnings, then proceed with code generation.".into()
        } else {
            "Ready for code generation.".into()
        }
    } else {
        let first = blockers.first().map(|s| s.as_str()).unwrap_or("");
        if first.contains("Customer") {
            "Set customer/environment for this task.".into()
        } else if first.contains("Repository root") {
            "Set repository root via Developer Target Setup.".into()
        } else if first.contains("setup has not been confirmed") {
            "Complete and confirm the developer setup.".into()
        } else if first.contains("Technical implementation") {
            "Generate a technical implementation plan.".into()
        } else if first.contains("Dataverse metadata") {
            "Run Dataverse metadata verification or mark it as not required.".into()
        } else if first.contains("Plugin project") {
            "Select the plugin project.".into()
        } else if first.contains("Target entity") {
            "Specify the target entity logical name in the technical plan.".into()
        } else if first.contains("Plugin registration") {
            "Specify message, stage, and execution mode in the technical plan.".into()
        } else if first.contains("Script creation requires") {
            "Set target directory and file name for script creation in Developer Target Setup."
                .into()
        } else if first.contains("Script update requires") {
            "Set the existing script file path in Developer Target Setup.".into()
        } else if first.contains("Target script") {
            "Set the target script path via Developer Target Setup.".into()
        } else if first.contains("Form/event") {
            "Add form/event details to the technical plan, or mark form registration as manual-later.".into()
        } else {
            "Resolve all blockers before proceeding with implementation.".into()
        }
    };

    serde_json::json!({
        "isImplementationReady": is_ready,
        "blockers": blockers,
        "warnings": warnings,
        "recommendedNextStep": recommended,
    })
}

